window.RA_DATA.lines = [
  { id: "ds-s1", kind: "scene", book_id: "dead-souls", place_ids: ["ru-gogol-house"], location: "Volume 1, Chapter 11", location_zh: "第一卷第十一章", text_en: "Chichikov, a smooth swindler, travels the provinces buying up 'dead souls', serfs who have died since the last census, to mortgage them as if they were alive. When the scheme leaks out he flees in his troika, and the book ends with Russia itself racing like a troika into the distance: 'Rus, where are you flying? Give an answer!'", text_zh: "圆滑的骗子乞乞科夫在外省四处收购“死魂灵”——上次人口登记后已死去的农奴，打算拿去当活人抵押。事情败露后他坐着三驾马车逃走，第一卷在这里结束：整个俄罗斯也像一辆三驾马车奔向远方——“罗斯，你奔向哪里？给个答复吧！”", highlight_en: ["where are you flying?"], highlight_zh: ["你奔向哪里？"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Dead_Souls" },
  { id: "fs-s1", kind: "scene", book_id: "fathers-and-sons", place_ids: ["ru-spasskoye"], location: "Chapter 27", location_zh: "第二十七章", text_en: "Bazarov, the young nihilist who believes in nothing but science, cuts his finger while dissecting the body of a peasant who died of typhus. Dying in his old parents' small house, he sends for Madame Odintsova, the woman he loved, and asks her: 'Breathe on the dying lamp, and let it go out.'", text_zh: "只相信科学、什么都不信的年轻虚无主义者巴扎罗夫，在解剖一个死于伤寒的农民尸体时割破了手指。他在年迈父母的小屋里奄奄一息，派人请来他爱过的奥津佐娃，对她说：“吹一口气在这盏将灭的灯上，让它熄灭吧。”", highlight_en: ["Breathe on the dying lamp"], highlight_zh: ["吹一口气在这盏将灭的灯上"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Fathers_and_Sons_(novel)" },
  { id: "bk-s1", kind: "scene", book_id: "brothers-karamazov", place_ids: ["ru-staraya-russa"], location: "Epilogue", location_zh: "尾声", text_en: "After the funeral of little Ilyusha, the schoolboy who defended his humiliated father, Alyosha Karamazov gathers the boys by a big stone at the edge of the town and asks them never to forget this day and one another. The boys shout 'Hurrah for Karamazov!', and they all go off together to the funeral meal.", text_zh: "小伊柳沙曾为受辱的父亲挺身而出，在他的葬礼之后，阿辽沙·卡拉马佐夫把孩子们召集在城边的一块大石头旁，请他们永远不要忘记这一天，不要忘记彼此。孩子们高呼：“卡拉马佐夫万岁！”然后一起去吃丧宴。", highlight_en: ["Hurrah for Karamazov!"], highlight_zh: ["卡拉马佐夫万岁！"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Brothers_Karamazov" },
  { id: "gol-s1", kind: "scene", book_id: "golovlyov-family", place_ids: ["ru-spas-ugol"], location: "Final chapter", location_zh: "最后一章", text_en: "Porfiry Golovlyov, called Iudushka, 'little Judas', has talked his mother, brothers and sons into their graves with pious phrases. Left alone on the estate, drinking and slowly understanding what he has done, he slips out on a March night in Holy Week to visit his mother's grave, and is found frozen on the road the next morning.", text_zh: "波尔菲里·戈洛夫廖夫外号“犹杜什卡”（小犹大），用满口虔诚的空话把母亲、兄弟和儿子们一个个送进了坟墓。最后他独守庄园，酗酒，慢慢明白了自己干了什么。复活节前一周的一个三月夜晚，他偷偷出门去给母亲上坟，第二天早上被人发现冻死在路上。", highlight_en: ["little Judas"], highlight_zh: ["小犹大"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Golovlyov_Family" },
  { id: "stp-s1", kind: "scene", book_id: "the-steppe", place_ids: ["ru-taganrog-chekhov"], location: "Throughout", location_zh: "全篇", text_en: "Nine-year-old Yegorushka is sent from home to school in a distant town, and travels across the summer steppe first in a priest's carriage, then on top of a wool merchant's wagon train. Over days and nights he sees the windmills, the burial mounds and the carters' campfires, until a great thunderstorm breaks over the plain and soaks him to the skin.", text_zh: "九岁的叶戈鲁什卡要离家去远方的城里上学，先坐神父的马车，后来爬到一个羊毛商人的货车队顶上，穿越夏天的草原。一连几天几夜，他看见风车、古墓和车夫们的篝火，直到一场大雷雨在平原上炸开，把他浇得浑身湿透。", highlight_en: ["great thunderstorm"], highlight_zh: ["大雷雨"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Steppe_(novella)" },
  { id: "sea-s1", kind: "scene", book_id: "the-seagull", place_ids: ["ru-melikhovo"], location: "Acts 1 and 4", location_zh: "第一幕与第四幕", text_en: "On a country estate by a lake, young Treplev stages his symbolist play with Nina, the girl next door, as its only actress; his mother, a famous actress, laughs at it. Two years later Nina, abandoned by the writer Trigorin and failing on the stage, comes back on a stormy night and keeps repeating 'I am a seagull'. When she leaves, Treplev shoots himself.", text_zh: "在湖边的乡间庄园里，年轻的特里波列夫上演自己的象征主义剧本，唯一的演员是邻家姑娘妮娜，他那当名演员的母亲却当场嘲笑。两年后，被作家特里果林抛弃、在舞台上也不得志的妮娜，在一个风雨夜回来，反复说着“我是一只海鸥”。她走后，特里波列夫开枪自杀了。", highlight_en: ["I am a seagull"], highlight_zh: ["我是一只海鸥"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Seagull" },
  { id: "twe-s1", kind: "scene", book_id: "the-twelve", place_ids: ["ru-blok-apartment"], location: "Throughout", location_zh: "全诗", text_en: "Through a blizzard in revolutionary Petrograd twelve Red Guards march, swearing and shooting. One of them, Petrukha, kills his old girlfriend Katka by mistake in a shoot-out with her new lover. At the end the snow clears for a moment, and ahead of the marching twelve, carrying a red flag, walks Jesus Christ.", text_zh: "在革命的彼得格勒，十二个赤卫队员冒着暴风雪行进，一路骂着、开着枪。其中的彼得鲁哈在向她的新情人开枪时，误杀了自己的旧相好卡奇卡。诗的结尾，雪幕忽然掀开片刻，走在十二个人前面、举着红旗的，是耶稣基督。", highlight_en: ["Jesus Christ"], highlight_zh: ["耶稣基督"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Twelve_(poem)" },
  { id: "cit-s1", kind: "scene", book_id: "cloud-in-trousers", place_ids: ["ru-mayakovsky-museum"], location: "Part 1", location_zh: "第一部分", text_en: "In a hotel room in Odessa the young poet waits hour after hour for Maria, who promised to come at four. Midnight passes; when she finally arrives it is to tell him she is getting married. His heart catches fire, and he calls out to his mother that her son is 'beautifully ill'.", text_zh: "在敖德萨的一间旅馆客房里，年轻的诗人一小时又一小时地等着答应四点钟来的玛丽亚。午夜过去了，她终于来了，却是来告诉他自己要结婚了。他的心燃烧起来，他向母亲喊道：您的儿子“病得多美”。", highlight_en: ["in Odessa"], highlight_zh: ["敖德萨"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Cloud_in_Trousers" },
  { id: "we-s1", kind: "scene", book_id: "we-zamyatin", place_ids: ["ru-zamyatin-lebedyan"], location: "Records 1–40", location_zh: "第一至四十篇记事", text_en: "D-503, chief builder of the spaceship Integral, keeps a diary of life in the One State, where citizens live in glass houses, march to the Table of Hours and draw the blinds only for state-licensed sex. The rebel I-330 awakens in him a soul and a passion. At the end he undergoes the Great Operation that removes the imagination, and calmly watches her tortured.", text_zh: "宇宙飞船“积分号”的总设计师 D-503 写日记记录大一统王国的生活：公民住在玻璃房子里，按“作息时刻表”行动，只有在国家许可的性生活时才能放下窗帘。反叛者 I-330 唤醒了他的灵魂和激情。最后，他接受了切除想象力的“伟大手术”，平静地看着她受刑。", highlight_en: ["glass houses"], highlight_zh: ["玻璃房子"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/We_(novel)" },
  { id: "da-s1", kind: "scene", book_id: "dark-avenues", place_ids: ["ru-bunin-oryol"], location: "'Dark Avenues'", location_zh: "《幽暗的林荫道》", text_en: "On a rainy autumn day an ageing officer stops at a coaching inn on the high road and recognises the landlady, Nadezhda, as the serf girl he seduced and abandoned some thirty years before. She has never married and never forgiven him, and he once read her poems about 'dark avenues of lindens'. Driving away, he wonders what life would have been if he had not left her.", text_zh: "一个秋雨天，一位上了年纪的军官在大路边的驿站客栈歇脚，认出女店主娜杰日达就是他大约三十年前诱惑又抛弃的农奴姑娘。她终身未嫁，也从未原谅他；他当年曾给她念过写“椴树幽暗的林荫道”的诗。马车驶离时，他想，如果当初没有离开她，人生会是什么样子。", highlight_en: ["some thirty years before"], highlight_zh: ["大约三十年前"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Dark_Avenues" },
  { id: "mm-s1", kind: "scene", book_id: "master-and-margarita", place_ids: ["ru-patriarch-ponds"], location: "Chapters 1–3", location_zh: "第一至三章", text_en: "On a hot spring evening at Patriarch's Ponds, the editor Berlioz is explaining to the poet Bezdomny that Jesus never existed, when a foreign 'professor' sits down beside them and predicts that Berlioz will have his head cut off, because Annushka has already spilled the sunflower oil. Minutes later Berlioz slips on the oil, and a tram does the rest.", text_zh: "一个炎热的春日傍晚，在牧首湖边，编辑柏辽兹正对诗人无家汉说耶稣从未存在过，一位外国“教授”在他们身边坐下，预言柏辽兹会被砍掉脑袋，因为安努什卡已经把葵花籽油洒了。几分钟后，柏辽兹踩在油上滑倒，一辆电车完成了剩下的事。", highlight_en: ["sunflower oil"], highlight_zh: ["葵花籽油"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Master_and_Margarita" },
  { id: "hd-s1", kind: "scene", book_id: "heart-of-a-dog", place_ids: ["ru-prechistenka-24"], location: "Chapters 3–9", location_zh: "第三至九章", text_en: "Professor Preobrazhensky, a famous rejuvenation surgeon living in grand style in his flat, takes in the stray dog Sharik and transplants into him the testicles and pituitary gland of a dead petty criminal, Klim Chugunkin. Sharik becomes a man, Sharikov, who swears, drinks, chases cats and finds a job strangling them for the state, until the professor reverses the operation.", text_zh: "以返老还童手术闻名的普列奥布拉任斯基教授在豪华公寓里过着体面日子。他收留了流浪狗沙里克，给它移植了一个死去的小混混克利姆·丘贡金的睾丸和脑垂体。沙里克变成了人——沙里科夫，骂人、酗酒、追猫，还找到了为国家掐死野猫的差事，直到教授把手术逆转回去。", highlight_en: ["Klim Chugunkin"], highlight_zh: ["克利姆·丘贡金"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Heart_of_a_Dog" },
  { id: "qd-s1", kind: "scene", book_id: "quiet-flows-the-don", place_ids: ["ru-veshenskaya"], location: "Book 3 and the ending", location_zh: "第三部与结尾", text_en: "In 1919 the Cossacks of the Upper Don rise against the Reds, and Grigory Melekhov, who has already fought on both sides, commands a division of the rebels. After years of war he loses Aksinya, shot as they flee; at the very end he throws his rifle into the Don, crosses the ice to his home village, and lifts his small son in his arms.", text_zh: "1919 年，上顿河的哥萨克起来反抗红军，已经在两边都打过仗的葛利高里·麦列霍夫当上了暴动军的师长。多年征战之后，他在逃亡途中失去了中枪身亡的阿克西妮娅；在小说最后，他把枪扔进顿河，踏着冰走回家乡的村子，把小儿子抱在怀里。", highlight_en: ["throws his rifle into the Don"], highlight_zh: ["把枪扔进顿河"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/And_Quiet_Flows_the_Don" },
  { id: "pwh-s1", kind: "scene", book_id: "poem-without-a-hero", place_ids: ["ru-fountain-house"], location: "Part 1, '1913'", location_zh: "第一部《一九一三年》", text_en: "On New Year's Eve 1940, in her room in the Fountain House, the poet is visited by masked shadows from the Petersburg of 1913: poets, actresses and admirers of a vanished carnival. Among them is a young dragoon cornet who shot himself on the stairs of the actress he loved, a ghost Akhmatova keeps returning to as the Second World War approaches.", text_zh: "1940 年除夕，诗人在喷泉宫的房间里迎来了一群从 1913 年彼得堡来的戴面具的幽灵：一场已经消逝的狂欢里的诗人、女演员和追求者。他们当中有一个年轻的龙骑兵少尉，曾在心爱的女演员家的楼梯上开枪自杀。随着第二次世界大战临近，阿赫玛托娃一次又一次回到这个幽灵身上。", highlight_en: ["New Year's Eve 1940"], highlight_zh: ["1940 年除夕"], status: "draft", fact_source: "https://petersburg.pages.wm.edu/?p=3052" },
  { id: "req-s1", kind: "scene", book_id: "requiem-akhmatova", place_ids: ["ru-kresty"], location: "'Instead of a Preface'", location_zh: "《代序》", text_en: "In the terrible years of the Yezhov terror, Akhmatova spends seventeen months in the queues outside the Leningrad prisons, where her son is held. One day a woman with lips blue from cold, who has never heard of her, recognises her and whispers: 'Can you describe this?' 'I can,' she answers, and something like a smile passes over what was once the woman's face.", text_zh: "在叶若夫恐怖的可怕年代，阿赫玛托娃在关押儿子的列宁格勒监狱外排了十七个月的队。一天，一个冻得嘴唇发青、从没听说过她的女人认出了她，悄声问：“这个，您能写出来吗？”“能。”她回答。于是，一丝像是微笑的东西掠过了那张曾经是脸的面孔。", highlight_en: ["Can you describe this?"], highlight_zh: ["这个，您能写出来吗？"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Requiem_(Anna_Akhmatova)" },
  { id: "cot-s1", kind: "scene", book_id: "city-of-thieves", place_ids: ["ru-kresty"], location: "Chapters 1–3", location_zh: "第一至三章", text_en: "In the starving winter of the siege, seventeen-year-old Lev is caught looting a dead German airman after curfew and thrown into the Crosses, where he shares a cell with the brash young deserter Kolya. Instead of shooting them, an NKVD colonel gives them an impossible task: find a dozen eggs in Leningrad for his daughter's wedding cake.", text_zh: "在围城挨饿的冬天，十七岁的列夫在宵禁后搜一个德国飞行员尸体时被抓，扔进了十字监狱，和莽撞的年轻逃兵科利亚关在同一间牢房。内务部的一位上校没有枪毙他们，而是交给他们一个不可能完成的任务：在列宁格勒找到一打鸡蛋，给他女儿做结婚蛋糕。", highlight_en: ["a dozen eggs"], highlight_zh: ["一打鸡蛋"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/City_of_Thieves_(novel)" },
  { id: "zh-s1", kind: "scene", book_id: "doctor-zhivago", place_ids: ["ru-peredelkino"], location: "Part 14", location_zh: "第十四章", text_en: "Hiding from the Bolsheviks with Lara and her daughter, Yuri Zhivago spends a few weeks of winter in the abandoned house at Varykino, deep in the snowbound Urals. Wolves howl outside at night while he sits at the desk by lamplight writing poems, the poems that close the novel, before Lara is taken away from him for ever.", text_zh: "为了躲避布尔什维克，尤里·日瓦戈带着拉拉和她的女儿，在大雪封山的乌拉尔深处瓦雷金诺的空房子里住了几个冬日星期。夜里外面狼在嚎叫，他就着灯光坐在桌前写诗——正是小说最后附的那些诗；随后，拉拉被永远地从他身边带走了。", highlight_en: ["Wolves howl"], highlight_zh: ["狼在嚎叫"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Doctor_Zhivago_(novel)" },
  { id: "lf-s1", kind: "scene", book_id: "life-and-fate", place_ids: ["ru-pavlov-house"], location: "Part 1", location_zh: "第一部", text_en: "In the ruins of Stalingrad, Captain Grekov and a few dozen men hold 'House 6/1', cut off from their own lines. They argue freely, mock the commissars and live as equals, and Grekov dreams aloud of a Russia without collective farms. A commissar, Krymov, is sent to bring them to heel; soon afterwards the Germans storm the house and its defenders are killed.", text_zh: "在斯大林格勒的废墟里，格列科夫上尉带着几十个人守着与本方阵地断了联系的“6/1 号楼”。他们自由争论，嘲弄政委，彼此平等相待，格列科夫甚至大声幻想没有集体农庄的俄罗斯。政委克雷莫夫被派来整顿他们；不久，德军攻进大楼，守军战死。", highlight_en: ["House 6/1"], highlight_zh: ["6/1 号楼"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Life_and_Fate" },
  { id: "gul-s1", kind: "scene", book_id: "gulag-archipelago", place_ids: ["ru-solovki"], location: "Part 3, Chapter 2", location_zh: "第三部第二章", text_en: "Solzhenitsyn tells how, after the revolution, the Bolsheviks turned the ancient monastery on the White Sea islands into the Solovki camp, where guards held absolute power over the prisoners and punishments such as the cells of Sekirnaya Hill were invented. Here, he argues, the Archipelago 'rose from the sea' before it spread across the whole country.", text_zh: "索尔仁尼琴讲述革命之后，布尔什维克怎样把白海群岛上的古老修道院变成了索洛韦茨基营：看守对犯人握有绝对权力，谢基尔纳亚山禁闭室之类的刑罚也是在这里发明的。他认为，群岛正是在这里“从海中升起”，然后蔓延到了全国。", highlight_en: ["rose from the sea"], highlight_zh: ["从海中升起"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Gulag_Archipelago" },
  { id: "fc-s1", kind: "scene", book_id: "first-circle", place_ids: ["ru-lubyanka"], location: "Opening and closing chapters", location_zh: "开头与结尾各章", text_en: "On Christmas Eve 1949 the diplomat Innokenty Volodin rings the American embassy from a public phone to warn that a Soviet agent is about to receive atomic secrets. The prisoner-scientists of the Marfino sharashka are set to identify his recorded voice, and Volodin is arrested and taken into the Lubyanka, where step by step he is searched, stripped and photographed until he is only a number.", text_zh: "1949 年平安夜，外交官英诺肯季·沃洛金用公用电话打给美国大使馆，警告说有一名苏联特工即将拿到原子弹机密。马尔菲诺特种监狱里的囚犯科学家奉命从录音中辨认出他的声音，沃洛金被捕，押进卢比扬卡，一步步被搜身、剥光衣服、拍照，直到只剩下一个编号。", highlight_en: ["American embassy"], highlight_zh: ["美国大使馆"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/In_the_First_Circle" },
  { id: "kol-s1", kind: "scene", book_id: "kolyma-tales", place_ids: ["ru-mask-of-sorrow"], location: "'Trampling the Snow'", location_zh: "《踏雪》", text_en: "The opening piece of Kolyma Tales asks how a road is beaten through virgin snow. One man goes first, sweating and cursing, leaving deep, uneven tracks; the next ones step beside his prints, not in them, and only after the last has passed does a path exist. Those who follow walk an easy road, Shalamov writes, but it is the first who does the work.", text_zh: "《科雷马故事》的开篇问：在没人走过的雪地上，路是怎么踩出来的？一个人先走，汗流浃背，骂骂咧咧，留下一行深浅不一的脚印；后面的人踩在他脚印旁边，而不是踩进去，等最后一个人走过，才有了一条路。沙拉莫夫写道，后来的人走的是好走的路，干活的却是第一个人。", highlight_en: ["virgin snow"], highlight_zh: ["没人走过的雪地"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Kolyma_Tales" },
  { id: "hoe-s1", kind: "scene", book_id: "house-on-the-embankment", place_ids: ["ru-house-embankment"], location: "Throughout", location_zh: "全书", text_en: "Glebov, now a successful literary scholar, remembers the boys of the grand house on the embankment and the professor Ganchuk, whose daughter Sonya he meant to marry. After the war, when Ganchuk is denounced in a campaign at the institute, Glebov keeps quiet and lets him fall, and he has spent the years since forgetting that he did.", text_zh: "如今已是成功文学学者的格列鲍夫，回忆起滨河大楼里的少年伙伴，回忆起甘丘克教授——他本打算娶教授的女儿索尼娅。战后，甘丘克在学院的一场批判运动中被揭发，格列鲍夫保持沉默，任他倒下；此后的岁月里，他一直在努力忘掉自己做过的这件事。", highlight_en: ["keeps quiet"], highlight_zh: ["保持沉默"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_House_on_the_Embankment_(novel)" },
  { id: "mp-s1", kind: "scene", book_id: "moscow-petushki", place_ids: ["ru-kursky-station"], location: "'Moscow. On the way to the Kursky station'", location_zh: "《莫斯科。去库尔斯克车站的路上》", text_en: "Venichka wakes in a stairwell, has never seen the Kremlin however much he walks, and makes his way to the Kursky station, where the buffet will not serve sherry. On the morning train to Petushki, where his beloved and his little son wait, he drinks, philosophises, and gives recipes for cocktails such as 'Tear of a Komsomol Girl', but the train never quite arrives.", text_zh: "韦尼奇卡在一个楼梯间醒来。不管走多少路，他都从没见过克里姆林宫，最后又走到库尔斯克车站，车站餐厅却不卖雪利酒。在开往佩图什基的早班火车上——心爱的人和小儿子在那里等他——他一路喝酒，一路高谈阔论，还给出“共青团员之泪”之类鸡尾酒的配方，可火车始终没有真正到站。", highlight_en: ["Tear of a Komsomol Girl"], highlight_zh: ["共青团员之泪"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Moscow-Petushki" },
  { id: "ph-s1", kind: "scene", book_id: "pushkin-house", place_ids: ["ru-pushkin-house"], location: "Part 3", location_zh: "第三部", text_en: "Leva Odoevtsev, a promising young scholar from a family of scholars, is left on duty in the institute's empty museum over the November holiday. His old rival Mitishatyev turns up with bottles, and Leva challenges him to a duel that turns into a drunken rampage through the night museum, in which Pushkin's death mask is smashed. Whether the duel really happened, the novel leaves open.", text_zh: "出身学者世家、前途看好的年轻学者列瓦·奥多耶夫采夫，十一月节日期间被留在研究所空荡荡的博物馆里值班。他的老对头米季沙季耶夫拎着酒瓶来了，列瓦向他提出决斗，结果演变成一场在夜间博物馆里的醉酒大破坏，连普希金的死亡面具都被摔碎了。这场决斗究竟是否真的发生过，小说没有说破。", highlight_en: ["death mask"], highlight_zh: ["死亡面具"], status: "draft", fact_source: "https://kommersant.ru/doc/3819764" },
  { id: "phs-s1", kind: "scene", book_id: "pushkin-hills", place_ids: ["ru-mikhailovskoye"], location: "Throughout", location_zh: "全书", text_en: "Alikhanov, a Leningrad writer nobody will publish, drinking too much and with his marriage falling apart, takes a summer job as a tour guide at the Pushkin reserve. He lodges with the hard-drinking Mikhail Ivanovich, leads coach parties round the Pushkin shrines, and when his wife decides to emigrate to America with their daughter, cannot make himself follow.", text_zh: "列宁格勒作家阿利哈诺夫没人肯出版他的书，酒喝得太多，婚姻也快散了。他找了份夏季工作，到普希金保护区当导游。他寄住在酒鬼米哈伊尔·伊万诺维奇家，带着一车车游客参观普希金的各处圣地；妻子决定带着女儿移民美国，他却怎么也下不了决心跟去。", highlight_en: ["tour guide at the Pushkin reserve"], highlight_zh: ["普希金保护区当导游"], status: "draft", fact_source: "https://aif.ru/culture/book/o-chem-kniga-zapovednik-dovlatova-i-v-chem-ee-smysl" },
  { id: "mat-s1", kind: "scene", book_id: "farewell-to-matyora", place_ids: ["ru-irkutsk-znamensky"], location: "Throughout and ending", location_zh: "全书与结尾", text_en: "The village of Matyora, on an island in the Angara, is to be flooded by a new dam, and its people must move to a settlement on the mainland. Old Darya refuses to leave the graves of her ancestors; she washes and whitewashes her house before it is burned. In the last scene a few old women sit in the final hut while a boat searches for the island in thick fog.", text_zh: "安加拉河岛上的马焦拉村要被新修的水坝淹没，村民们必须搬到岸上的新居民点。老达丽娅不肯离开祖先的坟墓；房子被烧掉之前，她把它擦洗干净，刷了白灰。最后一个场面里，几个老太太坐在仅剩的小屋里，一条船在浓雾中寻找这座岛。", highlight_en: ["whitewashes her house"], highlight_zh: ["刷了白灰"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Farewell_to_Matyora" },
  { id: "lau-s1", kind: "scene", book_id: "laurus", place_ids: ["ru-pskov-kremlin"], location: "'The Book of Renunciation'", location_zh: "《弃绝之书》", text_en: "After the death of his beloved Ustina and their child, for which he blames himself, the healer Arseny takes her name and comes to Pskov as the holy fool Ustin. He sleeps in a cemetery, goes in rags and never speaks, yet still heals everyone who comes to him, while the loud holy fool Karp proclaims the end of the world for both of them.", text_zh: "心爱的乌斯京娜和孩子死后，医者阿尔谢尼把罪责全归于自己，取了她的名字，以圣愚“乌斯京”的身份来到普斯科夫。他睡在墓地，衣衫褴褛，从不说话，却依然给所有来找他的人治病；嗓门很大的圣愚卡尔普则替两人宣告世界末日。", highlight_en: ["holy fool Ustin"], highlight_zh: ["圣愚“乌斯京”"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Laurus_(novel)" },
  { id: "zul-s1", kind: "scene", book_id: "zuleikha", place_ids: ["ru-kazan-kremlin"], location: "Part 1", location_zh: "第一部", text_en: "In 1930 Zuleikha, a timid Tatar wife bullied by her husband and her blind mother-in-law, is dispossessed as a kulak after the Red Army commander Ignatov shoots her husband. She is taken by sleigh to Kazan and held in a crowded transit prison, where she learns she is pregnant, before the long train journey to Siberia and exile on the Angara.", text_zh: "1930 年，胆小的鞑靼媳妇祖列伊哈受尽丈夫和瞎眼婆婆的欺压。丈夫被红军指挥员伊格纳托夫枪杀后，她作为富农被剥夺了一切，坐雪橇被押到喀山，关进拥挤的转运监狱，在那里发现自己怀孕了。随后，她踏上去西伯利亚的漫长火车旅程，流放到安加拉河边。", highlight_en: ["transit prison"], highlight_zh: ["转运监狱"], status: "draft", fact_source: "https://gallerix.org/news/lit/202304/zuleyxa-otkryvaet-glaza-guzel-yaxina/" },
  { id: "cv-s1", kind: "scene", book_id: "chapaev-and-void", place_ids: ["ru-pushkin-statue-moscow"], location: "Chapter 1", location_zh: "第一章", text_en: "One February soon after the revolution, the poet Pyotr Void, fleeing the Cheka, walks down a snowy Tverskoy Boulevard past the bronze Pushkin, decked with a red banner for the revolution's anniversary. That night he will shoot an old acquaintance, read a revolutionary poem in a literary café and wake up as commissar to the Red commander Chapaev, or in a 1990s psychiatric ward.", text_zh: "革命后不久的一个二月，躲避契卡的诗人彼得·虚空走在积雪的特维尔林荫道上，经过为革命周年挂上红布条幅的青铜普希金像。当晚他将开枪打死一个老熟人，在文学咖啡馆里朗诵一首革命诗，然后醒来，成了红军指挥员夏伯阳的政委——或者，躺在 20 世纪 90 年代的精神病院里。", highlight_en: ["Tverskoy Boulevard"], highlight_zh: ["特维尔林荫道"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Chapayev_and_Void" },
  { id: "c44-s1", kind: "scene", book_id: "child-44", place_ids: ["ru-lubyanka"], location: "Part 1", location_zh: "第一部", text_en: "In 1953 Leo Demidov, a war hero and officer of the MGB, believes in the state he serves from the Lubyanka. When a colleague's small son is found dead by the railway tracks, Leo is ordered to tell the grieving family it was an accident, because in the Soviet paradise there can be no murder; the doubt it plants will cost him everything.", text_zh: "1953 年，战斗英雄、国家安全部军官列奥·杰米多夫在卢比扬卡任职，对自己效忠的国家深信不疑。一位同事的小儿子死在铁轨边，上级命令列奥告诉悲痛的家人那是意外，因为在苏维埃天堂里不可能有谋杀；这件事在他心里种下的怀疑，最终让他失去一切。", highlight_en: ["there can be no murder"], highlight_zh: ["不可能有谋杀"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Child_44" },
  { id: "gim-s1", kind: "scene", book_id: "gentleman-in-moscow", place_ids: ["ru-metropol"], location: "Book 1", location_zh: "第一卷", text_en: "On 21 June 1922 a Bolshevik tribunal spares Count Alexander Rostov, the author of a seditious poem, but sentences him to house arrest for life at the Metropol. Moved from his grand suite to a cramped attic room on the sixth floor, he makes a new life inside the hotel, befriending the nine-year-old Nina, who has a key to every door.", text_zh: "1922 年 6 月 21 日，布尔什维克法庭饶了写过一首“反动”诗的亚历山大·罗斯托夫伯爵一命，却判他在大都会酒店终身软禁。他从豪华套房被赶进六楼一间窄小的阁楼，在酒店里开始了新生活，还和手握每一扇门钥匙的九岁女孩尼娜成了朋友。", highlight_en: ["house arrest for life"], highlight_zh: ["终身软禁"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/A_Gentleman_in_Moscow" },
  { id: "sm-s1", kind: "scene", book_id: "speak-memory", place_ids: ["ru-rozhdestveno"], location: "Chapters 6 and 12", location_zh: "第六章与第十二章", text_en: "Nabokov recalls the summers of his boyhood on the family estates on the Oredezh: chasing butterflies through the bogs and forests near Vyra, and in 1915 falling in love with a girl he calls Tamara, meeting her secretly in the parks of Vyra and of his uncle's Rozhdestveno across the river, before the revolution sent him into exile for ever.", text_zh: "纳博科夫回忆少年时在奥列杰日河畔家族庄园里度过的夏天：在维拉附近的沼泽和树林里追捕蝴蝶；1915 年，他爱上了一个他称作“塔玛拉”的姑娘，在维拉和河对岸舅舅的罗日杰斯特韦诺庄园的林苑里偷偷约会，直到革命让他永远流亡异乡。", highlight_en: ["chasing butterflies"], highlight_zh: ["追捕蝴蝶"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Speak,_Memory" },
  // —— 11-22 quotations from Russian Wikisource, replacing the placeholder scene notes (add_ru3.py) ——
  { id: "avv-1", book_id: "life-of-avvakum", place_ids: ["ru-pustozersk"], location: "The Life: exile to Pustozersk", location_zh: "《行传》：流放普斯托泽尔斯克", text_orig: "Таже, братию казня, а меня не казня, сослали в Пустозерье. И я из Пустозерья послал к царю два послания: первое невелико, а другое больши.", highlight_orig: ["Пустозерье", "Пустозерья"], text_en: "Then, punishing the brethren but not punishing me, they exiled me to Pustozersk. And from Pustozersk I sent the tsar two epistles: the first not long, the other longer.", highlight_en: ["Pustozersk"], text_zh: "随后，他们惩处了弟兄们，却没有惩处我，把我流放到普斯托泽尔斯克。我从普斯托泽尔斯克给沙皇寄去两封书信：头一封不长，另一封长些。", highlight_zh: ["普斯托泽尔斯克"], translation: "own", status: "draft", checked: "Russian Wikisource, Житие протопопа Аввакума, им самим написанное (Аввакум) (no-break spaces written as spaces), 2026-11-22" },
  { id: "liza-1", book_id: "poor-liza", place_ids: ["ru-simonov"], location: "Opening", location_zh: "开篇", text_orig: "Но всего приятнее для меня то место, на котором возвышаются мрачные, готические башни Си…нова монастыря. Стоя на сей горе, видишь на правой стороне почти всю Москву, сию ужасную громаду домов и церквей, которая представляется глазам в образе величественного амфитеатра: великолепная картина, особливо когда светит на нее солнце, когда вечерние лучи его пылают на бесчисленных златых куполах, на бесчисленных крестах, к небу возносящихся!", highlight_orig: ["Си…нова монастыря"], text_en: "But the place I like best of all is where the gloomy Gothic towers of the Si…nov Monastery rise. Standing on this hill, you see on your right almost the whole of Moscow, that awful mass of houses and churches, which appears to the eye in the shape of a majestic amphitheatre: a magnificent picture, especially when the sun shines on it, when its evening rays blaze on countless golden domes, on countless crosses rising to the sky!", highlight_en: ["the Si…nov Monastery"], text_zh: "但我最喜欢的，是西……诺夫修道院那些阴郁的哥特式塔楼高耸的地方。站在这座山上，右边几乎可以望见整个莫斯科，那一大片吓人的房屋和教堂，在眼前呈现为一座宏伟的圆形剧场：这是一幅壮丽的图画，尤其是在阳光照耀的时候，当夕阳的余晖在无数金色圆顶、在无数直指天空的十字架上燃烧的时候！", highlight_zh: ["西……诺夫修道院"], translation: "own", status: "draft", checked: "Russian Wikisource, Бедная Лиза (Карамзин), 2026-11-22" },
  { id: "wfw-1", book_id: "woe-from-wit", place_ids: ["ru-griboyedov-moscow"], location: "Act IV, scene 14", location_zh: "第四幕第十四场", text_orig: "Вон из Москвы! сюда я больше не ездок.\nБегу, не оглянусь, пойду искать по свету,\nГде оскорбленному есть чувству уголок!..\nКарету мне, карету!", highlight_orig: ["Москвы"], text_en: "Out of Moscow! I'll come here no more.\nI'm running, I won't look back, I'll go and search the world\nfor a corner where wounded feeling has a place!..\nMy carriage, my carriage!", highlight_en: ["Moscow"], text_zh: "离开莫斯科！我再也不来这里了。\n我要跑，头也不回，到世界上去寻找\n一个能容下受伤感情的角落！……\n备车，给我备车！", highlight_zh: ["莫斯科"], translation: "own", status: "draft", checked: "Russian Wikisource, Горе от ума (Грибоедов)/ПСС 1911 (ВТ)/Действие IV, 2026-11-22" },
  { id: "one-1", book_id: "eugene-onegin", place_ids: ["ru-mikhailovskoye"], location: "Chapter 2, stanza I", location_zh: "第二章第一节", text_orig: "Деревня, где скучал Евгений,\nБыла прелестный уголок;\nТам друг невинных наслаждений\nБлагословить бы Небо мог.\nГосподский дом, уединенный,\nГорой от ветров огражденный,\nСтоял над речкою; вдали\nПред ним пестрели и цвели\nЛуга и нивы золотые.\nМелькали сёла здесь и там,\nСтада бродили по лугам,\nИ сени расширял густые\nОгромный, запущенный сад,\nПриют задумчивых Дриад.", highlight_orig: ["Деревня, где скучал Евгений"], text_en: "The village where Evgeny was bored\nwas a charming little corner;\na friend of innocent delights\nmight there have blessed the heavens.\nThe manor house, secluded,\nscreened from the winds by a hill,\nstood above a stream; far off\nbefore it meadows and golden cornfields\nlay bright with colour and in bloom.\nVillages glimpsed here and there,\nherds wandered over the meadows,\nand a huge neglected garden,\nthe haunt of pensive Dryads,\nspread wide its dense shade.", highlight_en: ["The village where Evgeny was bored"], text_zh: "叶甫盖尼在那儿苦闷的乡村\n原是个迷人的小角落；\n一个爱好纯真乐趣的人\n在那里会为上天祝福。\n地主的宅子孤零零的，\n有山岗替它挡住风，\n立在小河上方；远处，\n草地和金黄的田野\n在它前面斑斓开放。\n村落在这里那里闪现，\n牛羊在草地上漫游，\n一座荒芜的大花园\n铺开浓密的绿荫，\n是沉思的林中仙女的栖所。", highlight_zh: ["叶甫盖尼在那儿苦闷的乡村"], translation: "own", status: "draft", checked: "Russian Wikisource, Евгений Онегин (Пушкин)/ПСС 1977 (СО)/Глава 2, 2026-11-22" },
  { id: "bel-1", book_id: "tales-of-belkin", place_ids: ["ru-vyra"], location: "'The Stationmaster'", location_zh: "《驿站长》", text_orig: "В трех верстах от станции *** стало накрапывать, и через минуту проливной дождь вымочил меня до последней нитки. По приезде на станцию, первая забота была поскорее переодеться, вторая спросить себе чаю. «Эй, Дуня!» закричал смотритель, «поставь самовар, да сходи за сливками». При сих словах вышла из-за перегородки девочка лет четырнадцати, и побежала в сени. Красота ее меня поразила. «Это твоя дочка?» спросил я смотрителя. — «Дочка-с,» отвечал он с видом довольного самолюбия; «да такая разумная, такая проворная, вся в покойницу мать». Тут он принялся переписывать мою подорожную, а я занялся рассмотрением картинок, украшавших его смиренную, но опрятную обитель.", highlight_orig: ["станции ***", "смиренную, но опрятную обитель"], text_en: "Three versts from the *** station it began to spit with rain, and a minute later a downpour soaked me to the skin. On arriving at the station my first concern was to change as quickly as I could, my second to ask for tea. 'Hey, Dunya!' the stationmaster shouted, 'put the samovar on, and go and fetch some cream.' At these words a girl of about fourteen came out from behind the partition and ran into the passage. Her beauty struck me. 'Is that your daughter?' I asked the stationmaster. 'My daughter, sir,' he answered with an air of satisfied pride; 'and so sensible, so quick, the image of her late mother.' Then he set about copying out my travel order, and I busied myself looking at the pictures that adorned his humble but tidy dwelling.", highlight_en: ["the *** station", "his humble but tidy dwelling"], text_zh: "离***驿站还有三俄里时，开始落雨点，不一会儿一场倾盆大雨把我浇得透湿。到了驿站，我头一件事是赶紧换衣服，第二件是要茶。“喂，杜尼娅！”驿站长喊道，“把茶炊烧上，再去拿点奶油来。”话音刚落，隔板后面走出一个十四岁上下的小姑娘，跑进了门廊。她的美貌叫我吃了一惊。“这是你女儿？”我问驿站长。“是我女儿，先生，”他带着心满意足的得意神情回答，“又懂事，又麻利，跟她过世的娘一模一样。”接着他动手誊写我的驿马使用证，我便观赏起那些装点着他这间简陋却整洁的小屋的图画来。", highlight_zh: ["***驿站", "简陋却整洁的小屋"], translation: "own", status: "draft", checked: "Russian Wikisource, Станционный смотритель (Пушкин) (no-break spaces written as spaces), 2026-11-22" },
  { id: "bh-1", book_id: "bronze-horseman", place_ids: ["ru-bronze-horseman"], location: "Part 2, lines 448–460", location_zh: "第二部第 448–460 行", text_orig: "И он по площади пустой\nБежит и слышит за собой —\nКак будто грома грохотанье —\nТяжёло-звонкое скаканье\nПо потрясённой мостовой.\nИ, озарён луною бледной,\nПростёрши руку в вышине,\nЗа ним несётся Всадник Медный\nНа звонко-скачущем коне;\nИ во всю ночь безумец бедный,\nКуда стопы ни обращал,\nЗа ним повсюду Всадник Медный\nС тяжёлым топотом скакал.", highlight_orig: ["Всадник Медный"], text_en: "And over the empty square he runs\nand hears behind him,\nlike the rumbling of thunder,\na heavy, ringing gallop\nover the shaken roadway.\nAnd, lit by the pale moon,\nhis hand stretched out on high,\nthe Bronze Horseman races after him\non his ringing, galloping steed;\nand all night long, wherever\nthe poor madman turned his steps,\neverywhere the Bronze Horseman\ngalloped after him with heavy tread.", highlight_en: ["the Bronze Horseman"], text_zh: "他在空荡荡的广场上\n奔跑，听见身后——\n仿佛雷声隆隆——\n沉重而响亮的马蹄声\n踏过震颤的路面。\n惨白的月光照着，\n他高高伸出手臂，\n青铜骑士在后面追赶，\n骑着嘚嘚飞奔的骏马；\n这可怜的疯子整整一夜\n无论把脚步转向哪里，\n青铜骑士都在后面\n沉重地蹄声嗒嗒追来。", highlight_zh: ["青铜骑士"], translation: "own", status: "draft", checked: "Russian Wikisource, Медный всадник (Пушкин) (no-break spaces written as spaces; the page's line numbers left out), 2026-11-22" },
  { id: "hero-1", book_id: "hero-of-our-time", place_ids: ["ru-lermontov-duel"], location: "'Princess Mary', 11 May", location_zh: "《梅丽公爵小姐》，5 月 11 日", text_orig: "Вчера я приехал в Пятигорск, нанял квартиру на краю города, на самом высоком месте, у подошвы Машука: во время грозы облака будут спускаться до моей кровли. Нынче в пять часов утра, когда я открыл окно, моя комната наполнилась запахом цветов, растущих в скромном палисаднике. Ветки цветущих черешен смотрят мне в окна, и ветер иногда усыпает мой письменный стол их белыми лепестками. Вид с трех сторон у меня чудесный. На запад пятиглавый Бешту синеет, как «последняя туча рассеянной бури»; на север поднимается Машук, как мохнатая персидская шапка, и закрывает всю эту часть небосклона; на восток смотреть веселее: внизу передо мною пестреет чистенький, новенький городок, шумят целебные ключи, шумит разноязычная толпа, — а там, дальше, амфитеатром громоздятся горы все синее и туманнее, а на краю горизонта тянется серебряная цепь снеговых вершин, начинаясь Казбеком и оканчиваясь двуглавым Эльборусом… Весело жить в такой земле!", highlight_orig: ["Пятигорск", "у подошвы Машука"], text_en: "Yesterday I arrived in Pyatigorsk and took lodgings at the edge of the town, on the highest spot, at the foot of Mashuk: in a storm the clouds will come down to my roof. This morning at five, when I opened the window, my room filled with the scent of the flowers growing in the modest front garden. Branches of flowering cherry look in at my windows, and the wind sometimes strews my writing desk with their white petals. The view on three sides is wonderful. To the west five-peaked Beshtu shows blue, like 'the last cloud of a scattered storm'; to the north rises Mashuk, like a shaggy Persian hat, and hides all that part of the sky; to the east the view is merrier: below me spreads a clean, brand-new little town, the healing springs murmur, a crowd of many tongues murmurs, and there, further off, the mountains pile up like an amphitheatre, ever bluer and mistier, and on the edge of the horizon stretches a silver chain of snowy peaks, beginning with Kazbek and ending with two-headed Elbrus... It is a joy to live in such a land!", highlight_en: ["Pyatigorsk", "at the foot of Mashuk"], text_zh: "昨天我到了五山城，在城边最高的地方、马舒克山脚下租了一处住所：下雷雨时，云会一直降到我的屋顶上。今天早上五点钟，我打开窗户，屋里立刻充满了小前院里花朵的香气。开花的樱桃树枝探进我的窗口，风有时把白色的花瓣撒满我的书桌。三面的景色都美极了。西边，五峰的别什图山泛着蓝色，像“消散的暴风雨的最后一片云”；北边，马舒克山像一顶毛茸茸的波斯帽子耸立着，遮住了这一片天空；往东看更叫人愉快：脚下是一座干干净净、崭新的小城，疗养的泉水哗哗作响，操着各种语言的人群喧闹着，再远处，群山层层叠叠像一座圆形剧场，越远越蓝，越远越朦胧，地平线边上绵延着一道银色的雪峰链，从卡兹别克峰开始，到双峰的厄尔布鲁士峰为止……生活在这样的地方多么快活！", highlight_zh: ["五山城", "马舒克山脚下"], translation: "own", status: "draft", checked: "Russian Wikisource, Герой нашего времени (Лермонтов)/СО/Княжна Мери (no-break spaces written as spaces), 2026-11-22" },
  { id: "ovc-1", book_id: "the-overcoat", place_ids: ["ru-kalinkin-bridge"], location: "Ending", location_zh: "结尾", text_orig: "Но кто бы мог вообразить, что здесь еще не все об Акакии Акакиевиче, что суждено ему на несколько дней прожить шумно после своей смерти, как бы в награду за не примеченную никем жизнь. Но так случилось, и бедная история наша неожиданно принимает фантастическое окончание. По Петербургу пронеслись вдруг слухи, что у Калинкина моста и далеко подальше стал показываться по ночам мертвец в виде чиновника, ищущего какой-то утащенной шинели и под видом стащенной шинели сдирающий со всех плеч, не разбирая чина и звания, всякие шинели: на кошках, на бобрах, на вате, енотовые, лисьи, медвежьи шубы — словом, всякого рода меха и кожи, какие только придумали люди для прикрытия собственной.", highlight_orig: ["Калинкина моста"], text_en: "But who could have imagined that this was not yet all about Akaky Akakievich, that he was destined to live on noisily for a few days after his death, as if in reward for a life that no one had noticed? But so it happened, and our poor story unexpectedly takes a fantastic ending. Rumours suddenly spread through Petersburg that at the Kalinkin Bridge, and far beyond it, a dead man in the shape of a clerk had begun to appear at night, looking for some overcoat that had been stolen, and under the pretext of the stolen overcoat pulling from everyone's shoulders, regardless of rank and title, every kind of overcoat: catskin, beaver, wadded, raccoon, fox, bearskin coats; in a word, every kind of fur and skin that people have ever devised to cover their own.", highlight_en: ["the Kalinkin Bridge"], text_zh: "可是谁能想到，关于阿卡基·阿卡基耶维奇的事到这里还没有完，他命中注定要在死后热热闹闹地再活几天，仿佛是对他那无人注意的一生的补偿。然而事情就是这样，我们这个可怜的故事竟出人意料地有了一个离奇的结尾。彼得堡忽然传开了谣言，说在卡林金桥一带，以及更远的地方，夜里出现了一个官员模样的死人，在寻找一件被抢走的外套，并且借口找那件被抢的外套，不分官阶职衔，从所有人肩上扒下各种各样的外套：猫皮的、海狸皮的、棉絮的、浣熊皮的、狐皮的、熊皮的大衣——总之，凡是人们为了遮盖自己的皮而想出来的各种毛皮和皮革。", highlight_zh: ["卡林金桥"], translation: "own", status: "draft", checked: "Russian Wikisource, Шинель (Гоголь)/СС 1967 (СО) (no-break spaces written as spaces), 2026-11-22" },
  { id: "nose-1", book_id: "the-nose", place_ids: ["ru-kazan-cathedral"], location: "Chapter II", location_zh: "第二章", text_orig: "Он побежал за каретою, которая, к счастию, проехала недалеко и остановилась перед Казанским собором.\nОн поспешил в собор, пробрался сквозь ряд нищих старух с завязанными лицами и двумя отверстиями для глаз, над которыми он прежде так смеялся, и вошел в церковь. Молельщиков внутри церкви было немного; они все стояли только при входе в двери. Ковалев чувствовал себя в таком расстроенном состоянии, что никак не в силах был молиться, и искал глазами этого господина по всем углам. Наконец увидел его стоявшего в стороне. Нос спрятал совершенно лицо свое в большой стоячий воротник и с выражением величайшей набожности молился.", highlight_orig: ["Казанским собором"], text_en: "He ran after the carriage, which, luckily, did not go far and stopped in front of the Kazan Cathedral.\nHe hurried into the cathedral, made his way through the row of beggar women with their faces bound up and two holes for the eyes, whom he used to laugh at so much, and went into the church. There were few worshippers inside; they all stood just by the doors. Kovalyov felt so upset that he was quite unable to pray, and searched every corner with his eyes for that gentleman. At last he saw him standing to one side. The Nose had hidden his face completely in his big stand-up collar and was praying with an expression of the greatest piety.", highlight_en: ["the Kazan Cathedral"], text_zh: "他追着马车跑，幸好马车没走多远，就在喀山大教堂前停下了。\n他赶紧走进大教堂，穿过一排包着脸、只露出两个眼洞的乞讨老婆子——他从前总拿她们取笑——进了教堂。里面做祈祷的人不多，都只站在门口。科瓦廖夫心里乱成一团，根本没法祈祷，只顾用眼睛在各个角落里搜寻那位先生。最后他看见那人站在一旁。鼻子把脸整个藏在宽大的立领里，带着无比虔诚的神情在祈祷。", highlight_zh: ["喀山大教堂"], translation: "own", status: "draft", checked: "Russian Wikisource, Нос (Гоголь)/Глава II, 2026-11-22" },
  { id: "hun-1", book_id: "sportsmans-sketches", place_ids: ["ru-bezhin-meadow"], location: "'Bezhin Meadow'", location_zh: "《别任草地》", text_orig: "Я узнал наконец, куда я зашел. Этот луг славится в наших околотках под названием Бежина луга... Но вернуться домой не было никакой возможности, особенно в ночную пору; ноги подкашивались подо мной от усталости. Я решился подойти к огонькам и в обществе тех людей, которых принял за гуртовщиков, дождаться зари.", highlight_orig: ["Бежина луга"], text_en: "At last I realised where I had got to. This meadow is famous in our parts under the name of Bezhin Meadow... But there was no way of getting home, especially at night; my legs were giving way under me from tiredness. I decided to go down to the fires and wait for the dawn in the company of the men I took for drovers.", highlight_en: ["Bezhin Meadow"], text_zh: "我终于明白自己走到哪儿来了。这片草地在我们这一带很有名，叫做别任草地……可是要回家已经不可能了，尤其是在夜里；我累得两腿发软。我决定走到火堆那边去，和那些我当成是赶牲口的人一起等天亮。", highlight_zh: ["别任草地"], translation: "own", status: "draft", checked: "Russian Wikisource, Бежин луг (Тургенев), 2026-11-22" },
  { id: "gen-1", book_id: "home-of-the-gentry", place_ids: ["ru-noble-nest-oryol"], location: "Chapter 1, opening", location_zh: "第一章开篇", text_orig: "Весенний, светлый день клонился к вечеру; небольшие розовые тучки стояли высоко в ясном небе и, казалось, не плыли мимо, а уходили в самую глубь лазури.\nПеред раскрытым окном красивого дома, в одной из крайних улиц губернского города О… (дело происходило в 1842 году), сидели две женщины — одна лет пятидесяти, другая уже старушка, семидесяти лет.", highlight_orig: ["губернского города О…"], text_en: "A bright spring day was drawing towards evening; small pink clouds stood high in the clear sky and seemed not to float past but to go away into the very depths of the azure.\nBefore the open window of a handsome house, in one of the outlying streets of the provincial town of O… (this was in 1842), sat two women, one about fifty, the other already an old woman of seventy.", highlight_en: ["the provincial town of O…"], text_zh: "一个明媚的春日渐近黄昏；几朵粉红的小云高高停在晴朗的天空里，仿佛不是飘过去，而是退进了蔚蓝的深处。\n在省城O……的一条边远街道上，一座漂亮房子敞开的窗前（事情发生在1842年），坐着两个女人，一个五十岁上下，另一个已是七十岁的老太太。", highlight_zh: ["省城O……"], translation: "own", status: "draft", checked: "Russian Wikisource, Дворянское гнездо (Тургенев)/Глава 1 (no-break spaces written as spaces), 2026-11-22" },
  { id: "obl-1", book_id: "oblomov", place_ids: ["ru-gorokhovaya"], location: "Part 1, chapter 1, opening", location_zh: "第一部第一章开篇", text_orig: "В Гороховой улице, в одном из больших домов, народонаселения которого стало бы на целый уездный город, лежал утром в постели, на своей квартире, Илья Ильич Обломов.", highlight_orig: ["В Гороховой улице"], text_en: "In Gorokhovaya Street, in one of those big houses whose population would have made up a whole district town, Ilya Ilyich Oblomov lay in bed in his flat one morning.", highlight_en: ["Gorokhovaya Street"], text_zh: "在豌豆街一幢大楼里——楼里的住户多得足够组成一座县城——伊利亚·伊里奇·奥勃洛莫夫一天早上躺在他寓所的床上。", highlight_zh: ["豌豆街"], translation: "own", status: "draft", checked: "Russian Wikisource, Обломов (Гончаров)/Часть 1/Глава 1, 2026-11-22" },
  { id: "und-1", book_id: "notes-from-underground", place_ids: ["ru-anichkov-bridge"], location: "Part 2, chapter 1", location_zh: "第二部第一章", text_orig: "Иногда по праздникам я хаживал в четвертом часу на Невский и гулял по солнечной стороне. То есть я там вовсе не гулял, а испытывал бесчисленные мучения, унижения и разлития желчи; но того-то мне, верно, и надобно было. Я шмыгал, как вьюн, самым некрасивым образом, между прохожими, уступая беспрерывно дорогу то генералам, то кавалергардским и гусарским офицерам, то барыням; я чувствовал в эти минуты конвульсивные боли в сердце и жар в спине при одном представлении о мизере моего костюма, о мизере и пошлости моей шмыгающей фигурки.", highlight_orig: ["на Невский"], text_en: "Sometimes on holidays I used to go to the Nevsky at about four o'clock and stroll along the sunny side. That is, I didn't stroll there at all, but went through countless torments, humiliations and overflowings of bile; but that, no doubt, was just what I needed. I darted like an eel, in the most unsightly way, among the passers-by, constantly giving way now to generals, now to officers of the Horse Guards and the hussars, now to ladies; at those moments I felt convulsive pains in my heart and a hot flush down my back at the mere thought of the wretchedness of my clothes, of the wretchedness and vulgarity of my darting little figure.", highlight_en: ["the Nevsky"], text_zh: "有时逢到节假日，我下午四点来钟到涅瓦大街去，在向阳的那一边散步。其实我根本不是在散步，而是在经受数不清的折磨、屈辱和怒火中烧；不过，这大概正是我所需要的。我像泥鳅一样，以最难看的样子在行人中间钻来钻去，不停地给人让路，一会儿让将军，一会儿让近卫骑兵和骠骑兵军官，一会儿让太太们；这种时候，我一想到自己衣着的寒酸、想到我这钻来钻去的小身影的寒酸和猥琐，心里就一阵阵抽痛，脊背发烫。", highlight_zh: ["涅瓦大街"], translation: "own", status: "draft", checked: "Russian Wikisource, Записки из подполья (Достоевский)/Часть 2/Глава 1, 2026-11-22" },
  { id: "cp-1", book_id: "crime-and-punishment", place_ids: ["ru-raskolnikov-house"], location: "Part I, chapter I, opening", location_zh: "第一部第一章开篇", text_orig: "В начале июля, в чрезвычайно жаркое время, под вечер, один молодой человек вышел из своей каморки, которую нанимал от жильцов в С — м переулке, на улицу и медленно, как бы в нерешимости, отправился к К — ну мосту.\nОн благополучно избегнул встречи с своею хозяйкой на лестнице. Каморка его приходилась под самою кровлей высокого пятиэтажного дома и походила более на шкаф, чем на квартиру.", highlight_orig: ["С — м переулке", "высокого пятиэтажного дома"], text_en: "At the beginning of July, in an extremely hot spell, towards evening, a young man came out of the little room he rented from tenants in S— Lane into the street and slowly, as if undecided, set off towards K— Bridge.\nHe had safely avoided meeting his landlady on the stairs. His little room was right under the roof of a tall five-storey house and was more like a cupboard than a flat.", highlight_en: ["S— Lane", "a tall five-storey house"], text_zh: "七月初，天气异常炎热，傍晚时分，一个年轻人从他在С胡同向二房东租住的小屋里走到街上，慢慢地、仿佛犹豫不决地朝К桥走去。\n他顺利地避开了在楼梯上碰见女房东。他的小屋就在一座高高的五层楼房的屋顶底下，与其说是住房，不如说像个柜子。", highlight_zh: ["С胡同", "五层楼房"], translation: "own", status: "draft", checked: "Russian Wikisource, Преступление и наказание (Достоевский)/Часть I/Глава I (no-break spaces written as spaces), 2026-11-22" },
  { id: "idi-1", book_id: "the-idiot", place_ids: ["ru-pavlovsk"], location: "Part III, chapter V (Ippolit's 'Necessary Explanation')", location_zh: "第三部第五章（伊波利特的《必要的说明》）", text_orig: "Я спросил его, что он подразумевает под своими беспрерывными „деревьями“ и почему он мне так навязывает эти „деревья“, — и с удивлением узнал от него, что я сам будто бы на том вечере выразился, что приезжал в Павловск в последний раз посмотреть на деревья.", highlight_orig: ["Павловск"], text_en: "I asked him what he meant by his incessant 'trees' and why he kept pressing these 'trees' on me, and learned from him with surprise that I myself had supposedly said, that evening, that I had come to Pavlovsk to look at the trees for the last time.", highlight_en: ["Pavlovsk"], text_zh: "我问他，他那没完没了的“树”是什么意思，为什么老把这些“树”硬塞给我，结果我惊讶地从他那里得知，好像是我自己在那天晚上说过，我到巴甫洛夫斯克来，是为了最后看一看那些树。", highlight_zh: ["巴甫洛夫斯克"], translation: "own", status: "draft", checked: "Russian Wikisource, Идиот (Достоевский)/Часть III/Глава V (no-break spaces written as spaces), 2026-11-22" },
  { id: "wp-1", book_id: "war-and-peace", place_ids: ["ru-borodino"], location: "Volume 3, Part 2, chapter XXX", location_zh: "第三卷第二部第三十章", text_orig: "Войдя по ступенькам входа на курган, Пьер взглянул впереди себя и замер от восхищенья пред красотою зрелища. Это была та же панорама, которою он любовался вчера с этого кургана; но теперь вся эта местность была покрыта войсками и дымами выстрелов, и косые лучи яркого солнца, поднимавшегося сзади левее Пьера, кидали на нее в чистом утреннем воздухе пронизывающий с золотым и розовым оттенком свет и темные, длинные тени.\n…\nВсё это было оживленно, величественно и неожиданно; но то, что́ более всего поразило Пьера — это был вид самого поля сражения, Бородина и лощины над Колочею по обеим сторонам ее.", highlight_orig: ["Бородина"], text_en: "Going up the steps onto the mound, Pierre looked ahead of him and froze in delight at the beauty of the spectacle. It was the same panorama he had admired from this mound the day before; but now the whole of this ground was covered with troops and the smoke of gunfire, and the slanting rays of the bright sun, rising behind and to the left of Pierre, cast on it, in the clear morning air, a piercing light with a gold and pink tinge, and dark, long shadows.\n…\nAll this was lively, majestic and unexpected; but what struck Pierre most of all was the sight of the battlefield itself, of Borodino and the hollow over the Kolocha on both sides of it.", highlight_en: ["Borodino"], text_zh: "皮埃尔踏着台阶走上土丘，向前一望，被眼前壮美的景象惊呆了。这还是昨天他在这座土丘上欣赏过的那片全景；可是现在，整个这片地方布满了军队和炮火的硝烟，明亮的太阳从皮埃尔身后偏左的地方升起，斜射的光线在清澈的晨空里给它洒上一层带着金色和玫瑰色的、穿透一切的光，投下长长的暗影。\n…\n这一切生气勃勃、雄伟壮观，出人意料；但最使皮埃尔震动的，是战场本身的景象：博罗季诺，以及科洛恰河两岸的洼地。", highlight_zh: ["博罗季诺"], translation: "own", status: "draft", checked: "Russian Wikisource, Война и мир (Толстой)/Том 3, 2026-11-22" },
  { id: "ak-1", book_id: "anna-karenina", place_ids: ["ru-obiralovka"], location: "Part VII, chapter XXX", location_zh: "第七部第三十章", text_orig: "— Прикажете до Обираловки? — сказал Петр.\nОна совсем забыла, куда и зачем она ехала, и только с большим усилием могла понять вопрос.\n— Да, — сказала она ему, подавая кошелек с деньгами, и, взяв на руку маленький красный мешочек, вышла из коляски.", highlight_orig: ["Обираловки"], text_en: "'To Obiralovka, madam?' said Pyotr.\nShe had quite forgotten where and why she was going, and only with a great effort could she understand the question.\n'Yes,' she said to him, handing him her purse, and, taking her little red bag on her arm, she got out of the carriage.", highlight_en: ["Obiralovka"], text_zh: "“您是要去奥比拉洛夫卡吧？”彼得说。\n她完全忘了自己要去哪里、为什么去，费了好大劲才听懂这个问题。\n“是的，”她对他说，把钱包递给他，挎起那个红色小手提包，下了马车。", highlight_zh: ["奥比拉洛夫卡"], translation: "own", status: "draft", checked: "Russian Wikisource, Анна Каренина (Толстой)/Часть VII/Глава XXX (no-break spaces written as spaces), 2026-11-22" },
  { id: "ak-2", book_id: "anna-karenina", place_ids: ["ru-obiralovka"], location: "Part VII, chapter XXXI", location_zh: "第七部第三十一章", text_orig: "И вдруг, вспомнив о раздавленном человеке в день ее первой встречи с Вронским, она поняла, что́ ей надо делать. Быстрым, легким шагом спустившись по ступенькам, которые шли от водокачки к рельсам, она остановилась подле вплоть мимо ее проходящего поезда.", highlight_orig: ["по ступенькам, которые шли от водокачки к рельсам"], text_en: "And suddenly, remembering the man who had been crushed on the day she first met Vronsky, she understood what she had to do. With a quick, light step she went down the steps that led from the water tower to the rails, and stopped right beside the train that was passing her.", highlight_en: ["the steps that led from the water tower to the rails"], text_zh: "她忽然想起她和弗龙斯基初次相遇那天被轧死的那个人，于是明白了自己该怎么做。她迈着轻快的步子，走下从水塔通向铁轨的台阶，紧挨着从她身旁驶过的列车站住。", highlight_zh: ["从水塔通向铁轨的台阶"], translation: "own", status: "draft", checked: "Russian Wikisource, Анна Каренина (Толстой)/Часть VII/Глава XXXI, 2026-11-22" },
  { id: "lm-1", book_id: "lady-macbeth-mtsensk", place_ids: ["ru-mtsensk"], location: "Chapter 1, opening", location_zh: "第一章开篇", text_orig: "Иной раз в наших местах задаются такие характеры, что, как бы много лет ни прошло со встречи с ними, о некоторых из них никогда не вспомнишь без душевного трепета. К числу таких характеров принадлежит купеческая жена Катерина Львовна Измайлова, разыгравшая некогда страшную драму, после которой наши дворяне, с чьего-то легкого слова, стали звать ее леди Макбет Мценского уезда.", highlight_orig: ["Мценского уезда"], text_en: "Now and then characters turn up in our parts of such a kind that, however many years have passed since you met them, you can never recall some of them without a tremor of the soul. Among such characters is the merchant's wife Katerina Lvovna Izmailova, who once played out a terrible drama, after which our gentry, from someone's light remark, took to calling her the Lady Macbeth of the Mtsensk District.", highlight_en: ["the Mtsensk District"], text_zh: "我们这一带有时会出这样的人物，不管同他们相遇已过去多少年，想起其中有些人来，心里总不免发颤。商人的妻子卡捷琳娜·利沃夫娜·伊兹梅洛娃就是这样一个人物，她曾经演出过一场可怕的悲剧，此后我们这里的贵族们，不知是谁随口一说，便叫她姆岑斯克县的麦克白夫人。", highlight_zh: ["姆岑斯克县"], translation: "own", status: "draft", checked: "Russian Wikisource, Леди Макбет Мценского уезда (Лесков), 2026-11-22" },
  { id: "ew-1", book_id: "enchanted-wanderer", place_ids: ["ru-konevets"], location: "Chapter 1, opening", location_zh: "第一章开篇", text_orig: "Мы плыли по Ладожскому озеру от острова Коневца к Валааму и на пути зашли по корабельной надобности в пристань к Кореле. Здесь многие из нас полюбопытствовали сойти на берег и съездили на бодрых чухонских лошадках в пустынный городок. Затем капитан изготовился продолжать путь, и мы снова отплыли.", highlight_orig: ["от острова Коневца к Валааму"], text_en: "We were sailing across Lake Ladoga from Konevets Island to Valaam, and on the way put in at the landing stage at Korela on ship's business. Here many of us were curious enough to go ashore, and drove on lively Finnish ponies into the desolate little town. Then the captain made ready to continue the voyage, and we sailed again.", highlight_en: ["from Konevets Island to Valaam"], text_zh: "我们乘船在拉多加湖上从科涅韦茨岛驶往瓦拉姆，途中因船上的事务在科列拉的码头靠了岸。我们当中许多人出于好奇上了岸，坐着芬兰人的矫健小马到那荒凉的小城里去了一趟。随后船长准备继续航行，我们又开船了。", highlight_zh: ["从科涅韦茨岛驶往瓦拉姆"], translation: "own", status: "draft", checked: "Russian Wikisource, Очарованный странник (Лесков)/Глава первая, 2026-11-22" },
  { id: "pt-1", book_id: "my-past-and-thoughts", place_ids: ["ru-sparrow-hills"], location: "Part 1, chapter 4", location_zh: "第一部第四章", text_orig: "Мы ушли от них вперед и, далеко опередивши, взбежали на место закладки Витбергова храма на Воробьевых горах.\nЗапыхавшись и раскрасневшись, стояли мы там, обтирая пот. Садилось солнце, купола блестели, город стлался на необозримое пространство под горой, свежий ветерок подувал на нас, постояли мы, постояли, оперлись друг на друга и, вдруг обнявшись, присягнули, в виду всей Москвы, пожертвовать нашей жизнью на избранную нами борьбу.", highlight_orig: ["на Воробьевых горах", "в виду всей Москвы"], text_en: "We went on ahead of them and, far in front, ran up to the site where Vitberg's church had been founded on the Sparrow Hills.\nOut of breath and flushed, we stood there wiping off the sweat. The sun was setting, the domes glittered, the city spread over an immeasurable space below the hill, a fresh breeze blew on us; we stood a while, stood, leaned on each other and, suddenly embracing, swore, in sight of all Moscow, to sacrifice our lives to the struggle we had chosen.", highlight_en: ["Sparrow Hills", "in sight of all Moscow"], text_zh: "我们走在他们前面，远远地把他们甩在后头，跑上了麻雀山上维特贝格大教堂的奠基处。\n我们气喘吁吁、满脸通红地站在那里擦汗。太阳正在落下，圆顶闪闪发光，城市在山下铺展成一望无际的一片，清新的微风吹拂着我们。我们站了一会儿，又站了一会儿，彼此倚靠着，忽然拥抱在一起，当着整个莫斯科宣誓：把我们的生命献给我们选定的斗争。", highlight_zh: ["麻雀山", "当着整个莫斯科"], translation: "own", status: "draft", checked: "Russian Wikisource, Былое и думы (Герцен)/Часть 1 (the page's line ends inside a paragraph joined), 2026-11-22" },
  { id: "ld-1", book_id: "lower-depths", place_ids: ["ru-bugrov-dosshouse"], location: "Act 1, opening stage direction", location_zh: "第一幕开场舞台说明", text_orig: "Подвал, похожий на пещеру. Потолок — тяжёлые, каменные своды, закопчённые, с обвалившейся штукатуркой. Свет — от зрителя и, сверху вниз, — из квадратного окна с правой стороны. Правый угол занят отгороженной тонкими переборками комнатой Пепла, около двери в эту комнату — нары Бубнова. В левом углу — большая русская печь, в левой, каменной, стене — дверь в кухню, где живут Квашня, Барон, Настя. Между печью и дверью у стены — широкая кровать, закрытая грязным ситцевым пологом. Везде по стенам — нары.", highlight_orig: ["Подвал, похожий на пещеру"], text_en: "A cellar like a cave. The ceiling: heavy stone vaults, sooty, with the plaster fallen off. The light comes from the audience and, from above downwards, through a square window on the right. The right-hand corner is taken up by Pepel's room, fenced off with thin partitions; by the door of this room are Bubnov's plank beds. In the left corner a big Russian stove; in the left-hand stone wall a door into the kitchen, where Kvashnya, the Baron and Nastya live. Between the stove and the door, against the wall, a wide bed hidden by a dirty cotton curtain. Plank beds everywhere along the walls.", highlight_en: ["A cellar like a cave"], text_zh: "一个像山洞的地下室。天花板是沉重的石头拱顶，熏得乌黑，灰泥已经剥落。光线从观众这边来，还从右边一扇方窗由上往下照进来。右边角落是用薄板隔出来的佩佩尔的小屋，小屋门边是布勃诺夫的板铺。左边角落里有一座大俄式炉子；左边石墙上有一扇门通厨房，克瓦什尼娅、男爵和娜斯佳住在那里。炉子和门之间靠墙放着一张宽床，挂着一块肮脏的印花布帐子。四面墙边全是板铺。", highlight_zh: ["像山洞的地下室"], translation: "own", status: "draft", checked: "Russian Wikisource, На дне (Горький)/ИС 1986 (no-break spaces written as spaces), 2026-11-22" },
  { id: "mot-1", book_id: "mother-gorky", place_ids: ["ru-sormovo"], location: "Part 1, chapter I, opening", location_zh: "第一部第一章开篇", text_orig: "Каждый день над рабочей слободкой, в дымном, масляном воздухе, дрожал и ревел фабричный гудок, и, послушные зову, из маленьких серых домов выбегали на улицу, точно испуганные тараканы, угрюмые люди, не успевшие освежить сном свои мускулы. В холодном сумраке они шли по немощеной улице к высоким каменным клеткам фабрики, она с равнодушной уверенностью ждала их, освещая грязную дорогу десятками жирных квадратных глаз. Грязь чмокала под ногами. Раздавались хриплые восклицания сонных голосов, грубая ругань зло рвала воздух, а встречу людям плыли иные звуки — тяжелая возня машин, ворчание пара. Угрюмо и строго маячили высокие черные трубы, поднимаясь над слободкой, как толстые палки.", highlight_orig: ["рабочей слободкой", "фабрики"], text_en: "Every day over the workers' settlement, in the smoky, oily air, the factory hooter shook and roared, and, obeying its call, sullen people who had not had time to refresh their muscles with sleep ran out of the small grey houses into the street like frightened cockroaches. In the cold half-light they walked along the unpaved street to the tall stone cages of the factory, which waited for them with indifferent assurance, lighting the muddy road with dozens of greasy square eyes. The mud squelched underfoot. Hoarse exclamations of sleepy voices rang out, coarse curses angrily tore the air, and towards the people floated other sounds: the heavy bustle of machines, the grumbling of steam. Gloomy and stern, the tall black chimneys loomed, rising over the settlement like thick sticks.", highlight_en: ["the workers' settlement", "the factory"], text_zh: "每天，在工人村的上空，在烟雾弥漫、油腻腻的空气里，工厂的汽笛颤抖着、吼叫着。听到它的召唤，还没来得及用睡眠恢复筋骨的阴郁的人们，像受惊的蟑螂一样，从一座座灰色的小房子里跑到街上。在寒冷的晨昏中，他们沿着没有铺石的街道走向工厂那一座座高大的石头笼子，工厂带着冷漠的自信等着他们，用几十只油腻的方眼睛照亮泥泞的道路。烂泥在脚下咕唧作响。睡意朦胧的嗓音发出沙哑的叫喊，粗野的咒骂恶狠狠地撕破空气，迎着人们飘来的是另一些声音：机器沉重的忙乱声，蒸汽的嘟囔声。高高的黑烟囱阴沉而严峻地耸立着，像一根根粗棍子竖在工人村上空。", highlight_zh: ["工人村", "工厂"], translation: "own", status: "draft", checked: "Russian Wikisource, Мать (Горький), 2026-11-22" },
  { id: "pet-1", book_id: "petersburg-bely", place_ids: ["ru-bronze-horseman"], location: "Chapter 6", location_zh: "第六章", text_orig: "Пустовала вся площадь.\nВ этот час полуночи на скалу упали и звякнули металлические копыта; конь зафыркал ноздрей в раскаленный туман; медное очертание Всадника теперь отделилось от конского крупа, а звенящая шпора нетерпеливо царапнула конский бок, чтобы конь слетел со скалы.\nИ конь слетел со скалы.\nПо камням понеслось тяжелозвонкое цоканье — через мост: к островам. Пролетел в туман Медный Всадник; у него в глазах была — зеленоватая глубина; мускулы металлических рук — распрямились, напружились; и рванулось медное темя; на булыжники конские обрывались копыта, на стремительных, на ослепительных дугах; конский рот разорвался в оглушительном ржании, напоминающем свистки паровоза; густой пар из ноздрей обдал улицу световым кипятком; встречные кони, фыркая, зашарахались в ужасе; а прохожие в ужасе закрывали глаза.", highlight_orig: ["на скалу", "Медный Всадник"], text_en: "The whole square was empty.\nAt that midnight hour metal hooves fell clanging onto the rock; the horse snorted into the incandescent mist; the bronze outline of the Horseman now separated from the horse's crupper, and the ringing spur scratched the horse's flank impatiently, so that the horse would leap down from the rock.\nAnd the horse leapt down from the rock.\nA heavy, ringing clatter rushed over the stones, across the bridge, to the islands. The Bronze Horseman flew past into the mist; in his eyes was a greenish depth; the muscles of his metal arms straightened, tensed; and the bronze crown of his head jerked forward; the horse's hooves came down on the cobbles in swift, dazzling arcs; the horse's mouth tore open in a deafening neigh like the whistle of a locomotive; thick steam from its nostrils scalded the street with luminous boiling water; horses coming the other way shied in terror, snorting; and passers-by shut their eyes in terror.", highlight_en: ["the rock", "The Bronze Horseman"], text_zh: "整个广场空无一人。\n在这午夜时分，金属的马蹄落在岩石上，铿然作响；马打着响鼻，喷进灼热的雾里；骑士的青铜轮廓此刻从马背上分离出来，叮当作响的马刺不耐烦地划了一下马肚，要马从岩石上跃下。\n马从岩石上跃了下来。\n沉重而响亮的嗒嗒声越过石头路，过了桥，奔向群岛。青铜骑士飞进雾里；他眼中是一片泛绿的深渊；金属手臂的肌肉伸直了，绷紧了；青铜的头顶猛地向前一冲；马蹄落在圆石路上，划出一道道迅疾而耀眼的弧线；马嘴张开，发出震耳欲聋的嘶鸣，像火车头的汽笛；鼻孔里喷出的浓浓蒸汽像发光的滚水浇在街上；迎面而来的马惊恐地打着响鼻往旁边躲；行人吓得闭上了眼睛。", highlight_zh: ["岩石", "青铜骑士"], translation: "own", status: "draft", checked: "Russian Wikisource, Петербург (Белый)/Версия 2 (no-break spaces written as spaces; the endnote asterisk after 'тяжелозвонкое' left out), 2026-11-22" },
  { id: "tc-1", book_id: "twelve-chairs", place_ids: ["ru-proval"], location: "Chapter XXXVI", location_zh: "第三十六章", text_orig: "Великий комбинатор двинулся стрелковым шагом по горной дороге, ведущей вокруг Машука к месту дуэли Лермонтова с Мартыновым, мимо санаториев и домов отдыха.\nОбгоняемый автобусами и пароконными экипажами, Остап вышел к Провалу.\nНебольшая, высеченная в скале галерея вела в конусообразный провал. Галерея кончалась балкончиком, стоя на котором можно было увидеть на дне Провала лужицу малахитовой зловонной жидкости. Этот Провал считается достопримечательностью Пятигорска, и поэтому за день его посещает немалое число экскурсий и туристов-одиночек.", highlight_orig: ["к Провалу"], text_en: "The great schemer set off at a rifleman's pace along the mountain road that leads round Mashuk to the spot where Lermontov fought his duel with Martynov, past sanatoriums and rest homes.\nOvertaken by buses and two-horse carriages, Ostap came out at the Proval.\nA small gallery cut into the rock led to a cone-shaped pit. The gallery ended in a little balcony, standing on which you could see at the bottom of the Proval a puddle of malachite-green, foul-smelling liquid. This Proval is considered one of the sights of Pyatigorsk, and so a good number of excursions and lone tourists visit it every day.", highlight_en: ["the Proval"], text_zh: "伟大的谋略家迈着步兵的步伐，沿着那条绕马舒克山通往莱蒙托夫与马丁诺夫决斗之地的山路走去，路过一座座疗养院和休养所。\n公共汽车和双马马车一辆辆超过他，奥斯塔普来到了普罗瓦尔。\n一条凿在岩石里的小坑道通向一个锥形的深坑。坑道尽头是个小阳台，站在上面能看见普罗瓦尔坑底一小汪孔雀石般碧绿、臭烘烘的水。这个普罗瓦尔被看作五山城的名胜，所以每天来参观的旅游团和散客为数不少。", highlight_zh: ["普罗瓦尔"], translation: "own", status: "draft", checked: "Russian Wikisource, Двенадцать стульев (Ильф и Петров)/Глава XXXVI, 2026-11-22" },
  // —— 11-23: fourth pack (tools/content/batches/add_ru4.py) ——
  { id: "cd-1", book_id: "captains-daughter", place_ids: ["ru-orenburg"], location: "Chapter 10, 'The Siege of the Town'", location_zh: "第十章《围城》", text_orig: "Приближаясь к Оренбургу, увидели мы толпу колодников с обритыми головами, с лицами, обезображенными щипцами палача. Они работали около укреплений, под надзором гарнизонных инвалидов. Иные вывозили в тележках сор, наполнявший ров; другие лопатками копали землю; на валу каменщики таскали кирпич и чинили городскую стену.", highlight_orig: ["Оренбургу"], text_en: "As we approached Orenburg we saw a crowd of convicts with shaven heads and faces disfigured by the executioner's tongs. They were working at the fortifications under the eye of the garrison invalids. Some were carting away the rubbish that filled the ditch, others were digging with spades; on the rampart masons were carrying bricks and mending the town wall.", highlight_en: ["Orenburg"], text_zh: "快到奥伦堡的时候，我们看见一群剃了头的囚犯，脸被刽子手的铁钳弄得不成样子。他们在驻防老兵的监督下修筑工事：有的用小车运走填满壕沟的垃圾，有的用铁锹挖土；土墙上，泥瓦匠搬着砖，修补城墙。", highlight_zh: ["奥伦堡"], translation: "own", status: "draft", checked: "Russian Wikisource, Капитанская дочка (Пушкин)/1978 (СО) (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "qs-1", book_id: "queen-of-spades", place_ids: ["ru-queen-of-spades-house"], location: "Chapter 2", location_zh: "第二章", text_orig: "Рассуждая таким образом, очутился он в одной из главных улиц Петербурга, перед домом старинной архитектуры. Улица была заставлена экипажами, кареты одна за другою катились к освещенному подъезду. Из карет поминутно вытягивались то стройная нога молодой красавицы, то гремучая ботфорта, то полосатый чулок и дипломатический башмак. Шубы и плащи мелькали мимо величавого швейцара. Германн остановился.\n— Чей это дом? — спросил он у углового будочника.\n— Графини ***, — отвечал будочник.\nГерманн затрепетал.", highlight_orig: ["домом старинной архитектуры"], text_en: "Reasoning thus, he found himself in one of the main streets of Petersburg, in front of a house of old-fashioned architecture. The street was crowded with carriages; one after another they rolled up to the lighted entrance. From the carriages there stretched out now the shapely foot of a young beauty, now a jingling jackboot, now a striped stocking and a diplomatic shoe. Fur coats and cloaks flashed past the stately doorman. Hermann stopped.\n'Whose house is this?' he asked the watchman at the corner.\n'The Countess ***'s,' answered the watchman.\nHermann shuddered.", highlight_en: ["a house of old-fashioned architecture"], text_zh: "他这样盘算着，不觉来到彼得堡的一条大街上，站在一幢老式建筑的房子前面。街上停满了马车，轿式马车一辆接一辆驶向灯火通明的大门。从车里不时伸出来的，一会儿是年轻美人匀称的脚，一会儿是叮当作响的长筒马靴，一会儿是条纹长袜和外交官的皮鞋。皮大衣和斗篷从威严的看门人身边一闪而过。赫尔曼站住了。\n“这是谁家的房子？”他问街角的岗警。\n“***伯爵夫人的。”岗警回答。\n赫尔曼打了个寒战。", highlight_zh: ["老式建筑的房子"], translation: "own", status: "draft", checked: "Russian Wikisource, Пиковая дама (Пушкин), 2026-11-23" },
  { id: "bg-1", book_id: "boris-godunov", place_ids: ["ru-novodevichy"], location: "Scene 'Maiden's Field. Novodevichy Convent'", location_zh: "《处女原野·新圣女修道院》一场", text_orig: "ДЕВИЧЬЕ ПОЛЕ\nНОВОДЕВИЧИЙ МОНАСТЫРЬ\n…\nОдин\nНельзя ли нам пробраться за ограду?\nДругой\nНельзя. Куды! и в поле даже тесно,\nНе только там. Легко ли? Вся Москва\nСперлася здесь; смотри: ограда, кровли,\nВсе ярусы соборной колокольни,\nГлавы церквей и самые кресты\nУнизаны народом.", highlight_orig: ["НОВОДЕВИЧИЙ МОНАСТЫРЬ"], text_en: "MAIDEN'S FIELD\nNOVODEVICHY CONVENT\n…\nONE\nCan't we get through, inside the wall?\nANOTHER\nNo chance. Even the field is packed,\nnever mind in there. No wonder: all Moscow\nhas crowded here; look: the wall, the roofs,\nevery tier of the cathedral belfry,\nthe domes of the churches, the very crosses\nare strung with people.", highlight_en: ["NOVODEVICHY CONVENT"], text_zh: "处女原野\n新圣女修道院\n…\n一人\n咱们能不能挤到围墙里面去？\n另一人\n不行。哪儿挤得进！连原野上都挤满了，\n更别说里面。也难怪：整个莫斯科\n都挤到这儿来了；你看：围墙、屋顶、\n教堂钟楼的每一层、\n各座教堂的圆顶，连十字架上\n都爬满了人。", highlight_zh: ["新圣女修道院"], translation: "own", status: "draft", checked: "Russian Wikisource, Борис Годунов (Пушкин) (the page prints this scene after the play, among the scenes left out of the final text; a gap marked …), 2026-11-23" },
  { id: "ts-1", book_id: "reminiscences-tsarskoye", place_ids: ["ru-lyceum"], location: "Stanza 2", location_zh: "第二节", text_orig: "Не здесь ли мирны дни вели земные боги?\nНе се ль Минервы росской храм?\nНе се ль Элизиум полнощный,\nПрекрасный Царскосельский сад,\nГде, льва сразив, почил орел России мощный\nНа лоне мира и отрад?", highlight_orig: ["Царскосельский сад"], text_en: "Was it not here the gods of earth spent days of peace?\nIs this not the temple of the Russian Minerva?\nIs this not the Elysium of the North,\nthe lovely garden of Tsarskoye Selo,\nwhere, having slain the lion, Russia's mighty eagle\nrested in the lap of peace and joy?", highlight_en: ["garden of Tsarskoye Selo"], text_zh: "尘世的众神不就是在这里安度太平岁月？\n这不就是俄罗斯弥涅耳瓦的神殿？\n这不就是北国的乐土，\n美丽的皇村花园——\n俄罗斯的雄鹰击败了狮子，\n在这里安卧于和平与欢乐的怀抱？", highlight_zh: ["皇村花园"], translation: "own", status: "draft", checked: "Russian Wikisource, Воспоминания в Царском Селе (Навис покров угрюмой нощи — Пушкин), 2026-11-23" },
  { id: "bor-1", book_id: "borodino-lermontov", place_ids: ["ru-borodino"], location: "Opening stanza", location_zh: "第一节", text_orig: "«Скажи-ка, дядя, ведь недаром\nМосква, спаленная пожаром,\nФранцузу отдана?\nВедь были ж схватки боевые,\nДа, говорят, еще какие!\nНедаром помнит вся Россия\nПро день Бородина!»", highlight_orig: ["Бородина"], text_en: "'Tell me, uncle, it was not for nothing\nthat Moscow, burned by fire,\nwas given up to the French?\nThere were battles, after all,\nand what battles, they say!\nNot for nothing does all Russia remember\nthe day of Borodino!'", highlight_en: ["Borodino"], text_zh: "“大叔，你说说，莫斯科烧成一片火海，\n交到法国人手里，\n总不是平白无故吧？\n不是打过好些仗吗，\n听说还打得真凶！\n难怪整个俄罗斯都记得\n波罗金诺那一天！”", highlight_zh: ["波罗金诺"], translation: "own", status: "draft", checked: "Russian Wikisource, Бородино (Лермонтов)/ПСС 1989 (СО), 2026-11-23" },
  { id: "np-1", book_id: "nevsky-prospekt", place_ids: ["ru-anichkov-bridge"], location: "Opening", location_zh: "开头", text_orig: "Нет ничего лучше Невского проспекта, по крайней мере в Петербурге; для него он составляет все. Чем не блестит эта улица — красавица нашей столицы!", highlight_orig: ["Невского проспекта"], text_en: "There is nothing finer than Nevsky Prospekt, at least in Petersburg; for the city it is everything. What does this street not shine with, the beauty of our capital!", highlight_en: ["Nevsky Prospekt"], text_zh: "再没有比涅瓦大街更好的了，至少在彼得堡是这样；对彼得堡来说，它就是一切。这条街——我们首都的美人——有什么不光彩夺目呢！", highlight_zh: ["涅瓦大街"], translation: "own", status: "draft", checked: "Russian Wikisource, Невский проспект (Гоголь)/Версия 2 (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "mu-1", book_id: "mumu", place_ids: ["ru-mumu-house"], location: "Opening", location_zh: "开头", text_orig: "В одной из отдаленных улиц Москвы, в сером доме с белыми колоннами, антресолью и покривившимся балконом, жила некогда барыня, вдова, окруженная многочисленною дворней. Сыновья ее служили в Петербурге, дочери вышли замуж; она выезжала редко и уединенно доживала последние годы своей скупой и скучающей старости.", highlight_orig: ["в сером доме с белыми колоннами"], text_en: "In one of the outlying streets of Moscow, in a grey house with white columns, a mezzanine and a balcony gone crooked, there once lived a lady, a widow, surrounded by a large household of serfs. Her sons were in the service in Petersburg, her daughters were married; she seldom went out and was living through the last years of her miserly and bored old age in solitude.", highlight_en: ["a grey house with white columns"], text_zh: "在莫斯科一条偏僻的街上，有一幢灰色的房子，带着白色圆柱、阁楼和歪斜的阳台，从前住着一位太太，是个寡妇，身边围着一大群家奴。她的儿子们在彼得堡做官，女儿们都出嫁了；她很少出门，孤零零地打发着她那吝啬而无聊的晚年。", highlight_zh: ["灰色的房子"], translation: "own", status: "draft", checked: "Russian Wikisource, Муму (Тургенев), 2026-11-23" },
  { id: "md-1", book_id: "house-of-the-dead", place_ids: ["ru-omsk-fortress"], location: "Part 1, chapter 1, 'The House of the Dead'", location_zh: "第一部第一章《死屋》", text_orig: "Острог наш стоял на краю крепости, у самого крепостного вала. Случалось, посмотришь сквозь щели забора на свет божий: не увидишь ли хоть чего-нибудь? — и только и увидишь, что краешек неба да высокий земляной вал, поросший бурьяном, а взад и вперед по валу, день и ночь, расхаживают часовые; и тут же подумаешь, что пройдут целые годы, а ты точно так же подойдешь смотреть сквозь щели забора и увидишь тот же вал, таких же часовых и тот же маленький краешек неба, не того неба, которое над острогом, а другого, далекого, вольного неба.", highlight_orig: ["на краю крепости"], text_en: "Our prison stood at the edge of the fortress, right by the fortress rampart. Sometimes you would look through the chinks in the fence at God's world, hoping to see something, and all you would see was a strip of sky and the high earthen rampart overgrown with weeds, and the sentries pacing up and down it day and night; and then you would think that whole years would pass and you would come up in just the same way to look through the chinks in the fence and see the same rampart, the same sentries and the same small strip of sky, not the sky above the prison but another, far-off, free sky.", highlight_en: ["the edge of the fortress"], text_zh: "我们的监狱在要塞的边上，紧挨着要塞的土墙。有时从木栅的缝隙里向外面的世界张望，想看看能不能看到点什么——可是看到的只有一小片天空和长满杂草的高高的土墙，哨兵日夜在墙上走来走去；这时你就会想，整整多少年过去之后，你还是会这样走过来，从木栅的缝隙里向外看，看到的还是那道土墙，那些哨兵，那一小片天空——不是监狱上面的天空，而是另一片遥远的、自由的天空。", highlight_zh: ["要塞的边上"], translation: "own", status: "draft", checked: "Russian Wikisource, Записки из Мёртвого дома (Достоевский)/Часть 1/Глава 1 (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "lf-1", book_id: "lefty", place_ids: ["ru-tula-lefty"], location: "Chapter 4", location_zh: "第四章", text_orig: "А когда будешь ехать через Тулу, покажи моим тульским мастерам эту нимфозорию, и пусть они о ней подумают. Скажи им от меня, что брат мой этой вещи удивлялся и чужих людей, которые делали нимфозорию, больше всех хвалил, а я на своих надеюсь, что они никого не хуже. Они моего слова не проронят и что-нибудь сделают.", highlight_orig: ["через Тулу"], text_en: "And when you pass through Tula, show my Tula craftsmen this nymphosoria and let them think it over. Tell them from me that my brother marvelled at this thing and praised above all the foreigners who made the nymphosoria, but that I put my trust in my own people, that they are no worse than anyone. They will not let my word fall to the ground, and they will do something.", highlight_en: ["through Tula"], text_zh: "你路过图拉的时候，把这个“宁佛索利亚”给我的图拉师傅们看看，让他们琢磨琢磨。你替我告诉他们：我哥哥对这玩意儿赞叹不已，把造出它的外国人夸得比谁都高，可我信得过自己人，他们不比任何人差。他们不会把我的话当耳旁风，总会做出点什么来。", highlight_zh: ["图拉"], translation: "own", status: "draft", checked: "Russian Wikisource, Левша (Лесков)/Версия 2 (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "sa-1", book_id: "sakhalin-island", place_ids: ["ru-aleksandrovsk"], location: "Chapter 2", location_zh: "第二章", text_orig: "Переночевавши в де-Кастри, мы на другой день, 10 июля, в полдень пошли поперек Татарского пролива к устью Дуйки, где находится Александровский пост. Погода и в этот раз была тихая, ясная, какая здесь бывает очень редко. По совершенно гладкому морю, пуская вверх фонтаны, гуляли парочками киты, и это прекрасное, оригинальное зрелище развлекало нас на всем пути.", highlight_orig: ["Александровский пост"], text_en: "Having spent the night at De-Kastri, the next day, 10 July, at noon we set off across the Tatar Strait for the mouth of the Duika, where the Alexandrovsk post lies. This time too the weather was calm and clear, such as is very rare here. Over the perfectly smooth sea whales swam in pairs, sending up fountains, and this fine, unusual sight entertained us the whole way.", highlight_en: ["Alexandrovsk post"], text_zh: "在德卡斯特里过了一夜，第二天，7 月 10 日，中午我们横渡鞑靼海峡，驶向杜伊卡河口，亚历山德罗夫斯克哨所就在那里。这一次天气也是风平浪静、晴朗明亮，在这里很少见。平滑如镜的海面上，鲸鱼成双成对地游着，喷出水柱，这美妙而奇特的景象让我们一路上都不觉得闷。", highlight_zh: ["亚历山德罗夫斯克哨所"], translation: "own", status: "draft", checked: "Russian Wikisource, Остров Сахалин (Чехов)/Глава 02, 2026-11-23" },
  { id: "ku-1", book_id: "on-the-field-of-kulikovo", place_ids: ["ru-kulikovo"], location: "Poem 3", location_zh: "第三首", text_orig: "Орлий клёкот над татарским станом\nУгрожал бедой,\nА Непрядва убралась туманом,\nЧто княжна фатой.\nИ с туманом над Непрядвой спящей,\nПрямо на меня\nТы сошла, в одежде свет струящей,\nНе спугнув коня.", highlight_orig: ["Непрядва"], text_en: "An eagle's scream above the Tatar camp\nthreatened disaster,\nand the Nepryadva dressed herself in mist\nas a princess in a veil.\nAnd with the mist over the sleeping Nepryadva,\nstraight towards me\nYou came down, in a robe streaming light,\nnot startling the horse.", highlight_en: ["Nepryadva"], text_zh: "鹰的唳叫在鞑靼营地上空\n预示着灾祸，\n涅普里亚德瓦河披上了雾，\n像公主披上面纱。\n随着雾笼罩沉睡的涅普里亚德瓦河，\n你径直向我\n走下来，衣裳流泻着光，\n没有惊动战马。", highlight_zh: ["涅普里亚德瓦河"], translation: "own", status: "draft", checked: "Russian Wikisource, На поле Куликовом (Блок)/3 (no-break and thin spaces written as plain spaces) (verse indent dropped), 2026-11-23" },
  { id: "cm-1", book_id: "poems-about-moscow", place_ids: ["ru-tsvetaeva-house"], location: "Poem 8", location_zh: "第八首", text_orig: "— Москва! — Какой огромный\nСтранноприимный дом!\nВсяк на Руси — бездомный.\nМы все к тебе придём.", highlight_orig: ["Москва"], text_en: "— Moscow! What a vast\nhouse for wayfarers!\nEveryone in Russia is homeless.\nWe shall all come to you.", highlight_en: ["Moscow"], text_zh: "——莫斯科！多么巨大的\n一座收留旅人的房子！\n在罗斯，人人无家可归。\n我们都将来到你这里。", highlight_zh: ["莫斯科"], translation: "own", status: "draft", checked: "Russian Wikisource, Стихи о Москве (Цветаева)/8, 2026-11-23" },
  { id: "ra-1", book_id: "journey-petersburg-moscow", place_ids: ["ru-vyshny-volochyok"], location: "Chapter 'Vyshny Volochok'", location_zh: "《上沃洛乔克》一章", text_orig: "Никогда не проезжал я сего нового города, чтобы не посмотреть здешних шлюзов. Первый, которому на мысль пришло уподобиться природе в ее благодеяниях и сделать реку рукодельною, дабы все концы единый области в вящее привести сообщение, достоин памятника для дальнейшего потомства.", highlight_orig: ["здешних шлюзов"], text_en: "I have never passed through this new town without looking at its locks. The first man to whom it occurred to imitate nature in her bounties and to make a river by hand, so as to bring all the ends of a single region into closer communication, deserves a monument for the most distant posterity.", highlight_en: ["its locks"], text_zh: "每次路过这座新城，我没有一次不去看看这里的船闸。头一个想到效法大自然的恩惠、用人工造出一条河来，好让一个地区的各个角落更便于往来的人，值得为后世子孙立一座纪念碑。", highlight_zh: ["这里的船闸"], translation: "own", status: "draft", checked: "Russian Wikisource, Путешествие из Петербурга в Москву (Радищев), 2026-11-23" },
  { id: "bag-1", book_id: "childhood-years-bagrov", place_ids: ["ru-ufa-aksakov"], location: "Chapter 'Ufa'", location_zh: "《乌法》一章", text_orig: "Обратный путь наш в Уфу совершился скорее и спокойнее: морозы стояли умеренные, окошечки в нашем возке не совсем запушались снегом, и возок не опрокидывался.\nВ Уфе все знакомые наши друзья очень нам обрадовались.", highlight_orig: ["в Уфу", "В Уфе"], text_en: "Our journey back to Ufa was quicker and calmer: the frosts were moderate, the little windows of our covered sledge did not fur over completely with snow, and the sledge did not overturn.\nIn Ufa all our friends were very glad to see us.", highlight_en: ["Ufa"], text_zh: "我们回乌法的路走得又快又平稳：天气不算太冷，带篷雪橇的小窗没有完全被雪糊住，雪橇也没有翻。\n到了乌法，所有相熟的朋友见到我们都非常高兴。", highlight_zh: ["乌法"], translation: "own", status: "draft", checked: "Russian Wikisource, Детские годы Багрова-внука (С. Т. Аксаков)/Уфа, 2026-11-23" },
  { id: "gi-1", book_id: "moscow-and-muscovites", place_ids: ["ru-khitrovka"], location: "Chapter 'Khitrovka'", location_zh: "《希特罗夫卡》一章", text_orig: "Лондон мне всегда представлялся самым туманным местом в Европе, а Хитров рынок, несомненно, — самым туманным местом в Москве.\nБольшая площадь в центре столицы, близ реки Яузы, окруженная облупленными каменными домами, лежит в низине, в которую спускаются, как ручьи в болото, несколько переулков. Она всегда курится. Особенно к вечеру. А чуть-чуть туманно или после дождя поглядишь сверху, с высоты переулка — жуть берет свежего человека: облако село! Спускаешься по переулку в шевелящуюся гнилую яму.", highlight_orig: ["Хитров рынок"], text_en: "London always seemed to me the foggiest place in Europe, and the Khitrov market, without doubt, the foggiest place in Moscow.\nA large square in the centre of the capital, near the river Yauza, surrounded by peeling stone houses, lies in a hollow into which several lanes run down like streams into a marsh. It is always steaming. Especially towards evening. And when it is a little misty, or after rain, you look from above, from the top of a lane, and a newcomer is seized with dread: a cloud has settled! You go down the lane into a stirring, rotten pit.", highlight_en: ["Khitrov market"], text_zh: "在我的想象里，伦敦一向是欧洲雾最大的地方，而希特罗夫市场无疑是莫斯科雾最大的地方。\n首都中心靠近亚乌扎河的一个大广场，四周是墙皮剥落的砖石房子，它躺在洼地里，几条小巷像溪水流进沼泽一样通到这里。它总是冒着雾气，傍晚尤其如此。稍微起点雾，或者刚下过雨，你从高处、从巷口往下看——初来的人会吓一跳：一团云落下来了！你顺着小巷走下去，走进一个蠕动着的烂泥坑。", highlight_zh: ["希特罗夫市场"], translation: "own", status: "draft", checked: "Russian Wikisource, Москва и москвичи (Гиляровский)/Хитровка (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "tam-1", book_id: "hero-of-our-time", place_ids: ["ru-taman"], location: "Pechorin's Journal, I: 'Taman'", location_zh: "毕巧林日记之一《塔曼》", text_orig: "Тамань — самый скверный городишко из всех приморских городов России. Я там чуть-чуть не умер с голода, да еще в добавок меня хотели утопить.", highlight_orig: ["Тамань"], text_en: "Taman is the nastiest little town of all the seaside towns of Russia. I nearly died of hunger there, and on top of that they tried to drown me.", highlight_en: ["Taman"], text_zh: "塔曼是俄国所有滨海城市中最糟糕的一个小城。我在那里差点儿饿死，而且还有人想把我淹死。", highlight_zh: ["塔曼"], translation: "own", status: "draft", checked: "Russian Wikisource, Герой нашего времени (Лермонтов)/СО/Тамань (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "eo-sg1", book_id: "eugene-onegin", place_ids: ["ru-summer-garden"], location: "Chapter 1, stanza III", location_zh: "第一章第三节", text_orig: "Monsieur l’Abbé, француз убогой,\nЧтоб не измучилось дитя,\nУчил его всему шутя,\nНе докучал моралью строгой,\nСлегка за шалости бранил\nИ в Летний сад гулять водил.", highlight_orig: ["Летний сад"], text_en: "Monsieur l'Abbé, a threadbare Frenchman,\nso as not to wear the child out,\ntaught him everything in jest,\ndid not bore him with stern morals,\nscolded him lightly for his pranks\nand took him walking in the Summer Garden.", highlight_en: ["Summer Garden"], text_zh: "Monsieur l'Abbé，一个穷酸的法国人，\n为了不让孩子太累，\n教他什么都像开玩笑，\n不拿严厉的道德说教烦他，\n淘气了也只是轻轻责备几句，\n还带他到夏花园去散步。", highlight_zh: ["夏花园"], translation: "own", status: "draft", checked: "Russian Wikisource, Евгений Онегин (Пушкин)/ПСС 1977 (СО)/Глава 1, 2026-11-23" },
  { id: "eo-pp1", book_id: "eugene-onegin", place_ids: ["ru-petrovsky-palace"], location: "Chapter 7, stanza XXXVII", location_zh: "第七章第三十七节", text_orig: "Вот, окружен своей дубравой,\nПетровский замок. Мрачно он\nНедавнею гордится славой.\nНапрасно ждал Наполеон,\nПоследним счастьем упоенный,\nМосквы коленопреклоненной\nС ключами старого Кремля:\nНет, не пошла Москва моя\nК нему с повинной головою.\nНе праздник, не приемный дар,\nОна готовила пожар\nНетерпеливому герою.\nОтселе, в думу погружен,\nГлядел на грозный пламень он.", highlight_orig: ["Петровский замок"], text_en: "There, ringed by its own oak wood,\nstands Petrovsky Castle. Gloomily\nit prides itself on recent glory.\nIn vain Napoleon waited here,\ndrunk with his last good fortune,\nfor Moscow on her knees\nwith the keys of the old Kremlin:\nno, my Moscow did not go\nto him with bowed and guilty head.\nNo holiday, no welcoming gift:\nshe was preparing a fire\nfor the impatient hero.\nFrom here, sunk in thought,\nhe gazed upon the dreadful flame.", highlight_en: ["Petrovsky Castle"], text_zh: "看，彼得罗夫宫被自己的橡树林环绕着。\n它阴沉地\n为不久前的荣耀而自豪。\n拿破仑陶醉于最后的幸运，\n在这里白白等待\n莫斯科屈膝跪下，\n献上古老克里姆林宫的钥匙：\n不，我的莫斯科没有\n低着认罪的头去见他。\n没有庆典，没有迎接的礼物，\n她给这位急不可耐的英雄\n准备的是一场大火。\n他就是从这里，陷入沉思，\n望着那可怕的火焰。", highlight_zh: ["彼得罗夫宫"], translation: "own", status: "draft", checked: "Russian Wikisource, Евгений Онегин (Пушкин)/ПСС 1977 (СО)/Глава 7, 2026-11-23" },
  { id: "cp-sn1", book_id: "crime-and-punishment", place_ids: ["ru-sennaya"], location: "Part 6, chapter 8", location_zh: "第六部第八章", text_orig: "Он вошел на Сенную.\n…\nОн стал на колени среди площади, поклонился до земли и поцеловал эту грязную землю, с наслаждением и счастием. Он встал и поклонился в другой раз.", highlight_orig: ["Сенную"], text_en: "He walked into the Haymarket.\n…\nHe knelt down in the middle of the square, bowed to the ground and kissed that filthy earth with delight and happiness. He got up and bowed a second time.", highlight_en: ["Haymarket"], text_zh: "他走进了干草市场。\n…\n他在广场中央跪下，向大地一躬到底，怀着快乐和幸福吻了吻这肮脏的土地。他站起来，又鞠了一躬。", highlight_zh: ["干草市场"], translation: "own", status: "draft", checked: "Russian Wikisource, Преступление и наказание (Достоевский)/Часть VI/Глава VIII (hard-wrapped lines joined, doubled spaces written as one) (a gap marked …), 2026-11-23" },
  { id: "gd-1", book_id: "childhood-gorky", place_ids: ["ru-kashirin-house"], location: "Chapter 1", location_zh: "第一章", text_orig: "Помню детскую радость бабушки при виде Нижнего. Дергая за руку, она толкала меня к борту и кричала:\n— Гляди, гляди, как хорошо! Вот он, батюшка, Нижний-то! Вот он какой, богов! Церкви-те, гляди-ка ты, летят будто!", highlight_orig: ["Нижнего"], text_en: "I remember grandmother's childlike joy at the sight of Nizhny. Tugging me by the hand, she pushed me to the rail and cried:\n'Look, look how fine it is! There he is, our Nizhny, bless him! That's what he's like, God's own town! The churches, look at them, they seem to be flying!'", highlight_en: ["Nizhny"], text_zh: "我记得外祖母看见下诺夫哥罗德时那孩子般的高兴。她拉着我的手，把我推到船舷边，喊道：\n“你看，你看，多好啊！这就是它，老天爷，下诺夫哥罗德！瞧它是什么样子，上帝的城！那些教堂，你瞧，就像在飞！”", highlight_zh: ["下诺夫哥罗德"], translation: "own", status: "draft", checked: "Russian Wikisource, Детство (Горький)/I, 2026-11-23" },
  { id: "wp-pk1", book_id: "war-and-peace", place_ids: ["ru-poklonnaya"], location: "Volume 3, part 3, chapter 19", location_zh: "第三卷第三部第十九章", text_orig: "В это же время, в 10 часов утра 2-го сентября, Наполеон стоял между своими войсками на Поклонной горе и смотрел на открывшееся перед ним зрелище.", highlight_orig: ["Поклонной горе"], text_en: "At that same time, at ten in the morning of 2 September, Napoleon was standing among his troops on Poklonnaya Hill and looking at the sight that lay open before him.", highlight_en: ["Poklonnaya Hill"], text_zh: "就在这个时候，9 月 2 日上午十点，拿破仑站在自己的军队中间，在俯首山上望着展现在他面前的景象。", highlight_zh: ["俯首山"], translation: "own", status: "draft", checked: "Russian Wikisource, Война и мир (Толстой)/Том 3, 2026-11-23" },
  { id: "ms-1", book_id: "michael-strogoff", place_ids: ["ru-nizhny-fair"], location: "Part 1, chapter 5", location_zh: "第一部第五章", text_orig: "Nijni-Novgorod, qui en temps ordinaire ne compte que trente à trente-cinq mille habitants, en renfermait alors plus de trois cent mille, c’est-à-dire que sa population était décuplée. Cet accroissement était dû à la célèbre foire qui se tient dans ses murs pendant une période de trois semaines. Autrefois, c’était Makariew qui bénéficiait de ce concours de marchands, mais, depuis 1817, la foire a été transportée à Nijni-Novgorod.", highlight_orig: ["Nijni-Novgorod"], text_en: "Nizhny Novgorod, which in ordinary times has no more than thirty to thirty-five thousand inhabitants, then held more than three hundred thousand; that is, its population had grown tenfold. This increase was due to the famous fair held within its walls for a period of three weeks. Formerly it was Makaryev that profited from this gathering of merchants, but since 1817 the fair has been moved to Nizhny Novgorod.", highlight_en: ["Nizhny Novgorod"], text_zh: "下诺夫哥罗德平时只有三万到三万五千居民，这时却容纳了三十多万人，也就是说人口增加了十倍。这是因为那个著名的集市，它在城里举行，为期三周。从前坐享商贾云集之利的是马卡里耶夫，但自 1817 年起，集市迁到了下诺夫哥罗德。", highlight_zh: ["下诺夫哥罗德"], translation: "own", status: "draft", checked: "French Wikisource, Michel Strogoff/Partie 1/Chapitre 5, 2026-11-23" },
  { id: "ml-1", book_id: "in-the-forests", place_ids: ["ru-svetloyar"], location: "Book 2, part 4, chapter 1", location_zh: "第二卷第四部第一章", text_orig: "Одно только помнит народ, что в старину на холмах у Светлого Яра на день Аграфены Купальницы языческие требища справлялись и что на тех холмах стоял когда-то град Китеж… И поныне, сказывают, стоит тот град, но видим бывает только очам праведников.", highlight_orig: ["Светлого Яра"], text_en: "One thing only the people remember: that in olden times, on the hills by Svetly Yar, pagan rites were held on the day of Agrafena Kupalnitsa, and that on those hills there once stood the city of Kitezh… And to this day, they say, that city stands, but it is visible only to the eyes of the righteous.", highlight_en: ["Svetly Yar"], text_zh: "人们只记得一件事：古时候，在斯韦特雷亚尔湖边的山丘上，每逢阿格拉费娜浴日都举行异教的祭礼，那些山丘上曾经矗立着基捷日城……据说这座城至今还在，只是唯有义人的眼睛才看得见。", highlight_zh: ["斯韦特雷亚尔湖"], translation: "own", status: "draft", checked: "Russian Wikisource, В лесах. Книга 2-я (Мельников-Печерский) (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "bug-s1", kind: "scene", book_id: "commandant-of-bugulma", place_ids: ["ru-bugulma"], location: "'The Commandant of the Town of Bugulma'", location_zh: "《布古利马城防司令》", text_en: "In October 1918 the narrator is sent out from Simbirsk with a small escort of Chuvash soldiers and arrives to take over Bugulma as its commandant. He has hardly settled in when Comrade Yerokhimov rides in at the head of the Tver Revolutionary Regiment and declares himself commandant instead, and the two go on issuing orders against each other.", text_zh: "1918 年 10 月，叙述者带着一小队楚瓦什士兵从辛比尔斯克出发，前来接管布古利马，当城防司令。他刚安顿下来，叶罗希莫夫同志就率领特维尔革命团骑马进城，宣布自己才是城防司令，两人从此你一道命令我一道命令地对着干。", highlight_en: ["Bugulma"], highlight_zh: ["布古利马"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Jaroslav_Hašek" },
  { id: "zh-s2", kind: "scene", book_id: "doctor-zhivago", place_ids: ["ru-perm"], location: "Part 9, 'Varykino'", location_zh: "第九章《瓦雷金诺》", text_en: "From Varykino Zhivago rides into Yuriatin to read in the town library, and one day sees Lara at a table across the reading room. He takes her address from her order slips and finds her in the yard of the house opposite the 'house with figures', carrying water from the well.", text_zh: "日瓦戈从瓦雷金诺骑马进尤里亚金城，到市图书馆看书，有一天隔着阅览室看见拉拉坐在一张桌子旁。他从她的借书单上抄下地址，在“有雕像的房子”对面那幢房子的院子里找到了她，她正从井边挑水回来。", highlight_en: ["Yuriatin", "house with figures"], highlight_zh: ["尤里亚金", "有雕像的房子"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Doctor_Zhivago_(novel)" },
  { id: "arz-s1", kind: "scene", book_id: "life-of-arseniev", place_ids: ["ru-yelets"], location: "Book 2", location_zh: "第二卷", text_en: "Sent to the gymnasium in the district town, the boy Alyosha Arseniev is boarded with the tradesman Rostovtsev. What stays with him is the town itself: the walk to school through frosty streets, the evenings at his landlord's table, and the pride with which that plain, stern man speaks of Russia.", text_zh: "少年阿廖沙·阿尔谢尼耶夫被送到县城上中学，寄住在小市民罗斯托夫采夫家里。留在他记忆里的是这座城本身：穿过结霜的街道去上学的路，房东饭桌旁的夜晚，还有这个朴素而严厉的人说起俄罗斯时的那份自豪。", highlight_en: ["the district town"], highlight_zh: ["县城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Life_of_Arseniev" },
  { id: "vor-s1", kind: "scene", book_id: "voronezh-notebooks", place_ids: ["ru-voronezh-mandelstam"], location: "The three notebooks, 1935–1937", location_zh: "三本笔记本，1935—1937", text_en: "Exiled to Voronezh after his first arrest, Mandelstam began to write again in the spring of 1935. The poems of the three notebooks take in the black earth of the fields around, the steep streets of the town and his own confinement in it. His wife Nadezhda kept them, on paper and by heart, through the decades when they could not be printed.", text_zh: "第一次被捕后流放到沃罗涅日的曼德尔施塔姆，1935 年春天重新开始写诗。三本笔记本里的诗写到了四周田野的黑土，城里陡峭的街道，也写到他被困在这里的处境。在这些诗无法发表的几十年里，他的妻子娜杰日达靠纸和记忆把它们保存了下来。", highlight_en: ["Voronezh"], highlight_zh: ["沃罗涅日"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Osip_Mandelstam" },
  { id: "mes-s1", kind: "scene", book_id: "meshchora-side", place_ids: ["ru-solotcha"], location: "'An Ordinary Land'", location_zh: "《平凡的土地》", text_en: "Paustovsky begins by admitting that the Meshchora country has no special beauties or riches, nothing but forests, meadows and clear air, and that it holds you all the same. Chapter by chapter he goes through its lakes and peat bogs, its old canals and forest rivers, and the ferrymen, basket-weavers and old men he met along them.", text_zh: "帕乌斯托夫斯基开篇就承认，梅晓拉地区没有什么特别的美景和财富，只有森林、草地和清澈的空气，可它偏偏叫人放不下。他一章一章地写这里的湖泊和泥炭沼泽、旧运河和林间小河，还有一路上遇到的摆渡人、编筐人和老人们。", highlight_en: ["Meshchora"], highlight_zh: ["梅晓拉"], status: "draft", fact_source: "https://ru.wikipedia.org/wiki/Паустовский,_Константин_Георгиевич" },
  { id: "matr-s1", kind: "scene", book_id: "matryonas-place", place_ids: ["ru-miltsevo"], location: "Whole story", location_zh: "全篇", text_en: "In the summer of 1956 a teacher back from the camps asks to be sent to some quiet corner of Russia, and takes a bed in the old house of Matryona, a sick, unpaid, uncomplaining peasant woman who helps everyone. She is killed at the railway crossing, helping to haul away the timbers of her own annexe, and only then does he see that she was the righteous one without whom no village can stand.", text_zh: "1956 年夏天，一位从劳改营回来的教师请求分配到俄罗斯某个安静的角落，在玛特辽娜的老屋里借了一张床。玛特辽娜是个多病、没有报酬、从不抱怨、谁家有事都去帮忙的农妇。她在铁路道口帮人拖运从自家偏屋拆下的木料时被火车撞死，直到这时他才明白，她就是那种义人，少了这样的人，一个村子就立不住。", highlight_en: ["some quiet corner of Russia"], highlight_zh: ["俄罗斯某个安静的角落"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Matryona's_Place" },
  { id: "lb-s1", kind: "scene", book_id: "last-bow", place_ids: ["ru-ovsyanka"], location: "'The Horse with the Pink Mane'", location_zh: "《粉红色鬃毛的马》", text_en: "The boy is sent to the hillside to pick strawberries for his grandmother to sell in town. The neighbour's children dare him into eating them, and he pads the basket with grass under a layer of berries. His grandmother finds out when she takes the basket to town, comes home scolding, and still brings him the gingerbread horse with the pink mane that she had promised.", text_zh: "外祖母打发男孩上山坡摘草莓，好拿到城里去卖。邻居家的孩子们激他把草莓吃掉了，他就在筐里塞满草，上面铺一层草莓。外祖母把筐带进城才发现上了当，回家把他数落了一通，可还是把答应过的那匹粉红色鬃毛的蜜糖饼小马带给了他。", highlight_en: ["the hillside"], highlight_zh: ["山坡"], status: "draft", fact_source: "https://ru.wikipedia.org/wiki/Астафьев,_Виктор_Петрович" },
  { id: "rah-s1", kind: "scene", book_id: "in-a-room-and-a-half", place_ids: ["ru-muruzi"], location: "The essay", location_zh: "全文", text_en: "Writing in English in America, after both his parents had died without being allowed to see him again, Brodsky rebuilds the space the three of them shared in a communal flat: the big room with its Moorish plaster ornament, and his own half-room, walled off with bookshelves and stacked suitcases.", text_zh: "布罗茨基在美国用英文写作此文时，父母都已去世，生前始终未获准再见他一面。他在文中重建了一家三口在合住公寓里共用的那点空间：带着摩尔式石膏装饰的大房间，以及他自己用书架和摞起来的箱子隔出来的那半间。", highlight_en: ["a communal flat"], highlight_zh: ["合住公寓"], status: "draft", fact_source: "https://ru.wikipedia.org/wiki/Полторы_комнаты" },
  { id: "fls-s1", kind: "scene", book_id: "front-line-stalingrad", place_ids: ["ru-mamayev-kurgan"], location: "Part 2", location_zh: "第二部", text_en: "Lieutenant Kerzhentsev, a sapper, has retreated with the army across the steppe to the Volga in the summer of 1942, and in Stalingrad he is given a battalion on the slope of Mamayev Kurgan. For weeks the war is a few hundred metres of trench, mines laid at night, and one more attempt on the water tanks at the top of the hill.", text_zh: "工兵中尉克尔任采夫在 1942 年夏天随部队穿过草原退到伏尔加河边，到斯大林格勒后受命带一个营守在马马耶夫岗的山坡上。一连几个星期，战争就是几百米长的战壕、夜里埋下的地雷，以及又一次向山顶水塔发起的冲击。", highlight_en: ["Mamayev Kurgan"], highlight_zh: ["马马耶夫岗"], status: "draft", fact_source: "https://ru.wikipedia.org/wiki/В_окопах_Сталинграда" },
  { id: "hp-s1", kind: "scene", book_id: "heart-of-parma", place_ids: ["ru-cherdyn"], location: "Whole novel", location_zh: "全书", text_en: "Prince Mikhail rules Perm the Great from the wooden fortress of Cherdyn. The Vogul prince Asyka comes raiding from beyond the Urals, and from the west Moscow sends first its bishops and then, in 1472, an army to take the land for the Grand Prince.", text_zh: "米哈伊尔公在切尔登的木头城堡里统治着“大彼尔姆”。沃古尔人的王公阿瑟卡从乌拉尔山那边前来劫掠；西边的莫斯科先派来主教，1472 年又派来军队，要把这片土地收归大公。", highlight_en: ["Cherdyn"], highlight_zh: ["切尔登"], status: "draft", fact_source: "https://ru.wikipedia.org/wiki/Сердце_пармы" },
  { id: "gp-s1", kind: "scene", book_id: "gorky-park", place_ids: ["ru-gorky-park"], location: "Part 1, 'Moscow'", location_zh: "第一部《莫斯科》", text_en: "Chief Investigator Arkady Renko of the Moscow militia is called out to a clearing in the park, where the thaw has uncovered three bodies: shot, and with their faces and fingertips cut away. Everything about the case says it belongs to the KGB, and the KGB insists that he keep it.", text_zh: "莫斯科民警局的首席侦查员阿尔卡季·伦科被叫到公园里的一片空地上，融雪露出了三具尸体：都是被枪杀的，脸和指尖都被割掉了。这桩案子处处显得该归克格勃管，克格勃却坚持让他办下去。", highlight_en: ["the park"], highlight_zh: ["公园"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Gorky_Park_(novel)" },
  { id: "wq-s1", kind: "scene", book_id: "winter-queen", place_ids: ["ru-alexander-garden"], location: "Chapter 1", location_zh: "第一章", text_en: "On 13 May 1876, in front of the strollers in the Alexander Garden, a well-dressed student goes up to a young lady on a bench, puts a revolver to his head and pulls the trigger. The file comes to the desk of a twenty-year-old clerk of the Criminal Investigation Division, Erast Fandorin.", text_zh: "1876 年 5 月 13 日，在亚历山大花园里，一个衣着体面的大学生当着散步人群的面，走到长椅上一位年轻小姐跟前，把左轮手枪顶在自己头上扣动了扳机。案卷送到了刑事侦缉处一个二十岁的文书埃拉斯特·凡多林的桌上。", highlight_en: ["Alexander Garden"], highlight_zh: ["亚历山大花园"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Winter_Queen_(novel)" },
  { id: "ca-s1", kind: "scene", book_id: "children-of-the-arbat", place_ids: ["ru-arbat"], location: "Part 1", location_zh: "第一部", text_en: "Sasha Pankratov, a student and Komsomol member from a big house on the Arbat, is expelled from his institute over a trifle, arrested, and in 1934 exiled to Siberia. The novel moves between him, the schoolfriends who stay behind on the Arbat, and Stalin.", text_zh: "萨沙·潘克拉托夫是住在阿尔巴特街一幢大楼里的大学生、共青团员。他因为一点小事被学院开除，接着被捕，1934 年流放西伯利亚。小说在他、留在阿尔巴特街的中学同学们和斯大林之间来回切换。", highlight_en: ["the Arbat"], highlight_zh: ["阿尔巴特街"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Children_of_the_Arbat" },
  { id: "de-s1", kind: "scene", book_id: "disappearing-earth", place_ids: ["ru-petropavlovsk"], location: "'August'", location_zh: "《八月》", text_en: "On an August afternoon two sisters, Alyona and Sophia, eleven and eight, are alone on the rocky shore of the bay when a man asks them to help him to his car. Each chapter after that is another month, and another woman of Kamchatka living in the shadow of their disappearance.", text_zh: "八月的一个下午，十一岁的阿廖娜和八岁的索菲娅姐妹俩独自在海湾的礁石岸边，一个男人请她们扶他走到车那里。此后每一章是一个月，写的是另一个生活在两姐妹失踪阴影下的堪察加女人。", highlight_en: ["the bay"], highlight_zh: ["海湾"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Disappearing_Earth" },
  { id: "mon-s1", kind: "scene", book_id: "the-monastery-prilepin", place_ids: ["ru-solovki"], location: "Book 1", location_zh: "第一部", text_en: "Artyom Goryainov, a young Muscovite, is serving his sentence in the Solovki camp at the end of the 1920s, when its chief Eichmanis still speaks of the place as a laboratory for making new men. The novel follows him from one work detail to the next, and to the punishment cells on Sekirnaya Hill.", text_zh: "年轻的莫斯科人阿尔乔姆·戈里亚伊诺夫 1920 年代末在索洛韦茨基劳改营服刑，当时的营长艾赫马尼斯还把这里说成一座改造新人的实验室。小说跟着他从一个劳动队换到另一个劳动队，最后到了谢基尔山上的禁闭室。", highlight_en: ["Solovki"], highlight_zh: ["索洛韦茨基"], status: "draft", fact_source: "https://ru.wikipedia.org/wiki/Обитель_(роман)" },
  { id: "mm-s2", kind: "scene", book_id: "master-and-margarita", place_ids: ["ru-bulgakov-house"], location: "Chapter 7, 'The Evil Apartment'", location_zh: "第七章《凶宅》", text_en: "Styopa Likhodeyev, director of the Variety Theatre, wakes with a hangover in flat no. 50 to find a stranger in black sitting by his bed, with a contract he cannot remember signing. A moment later he is standing on a jetty in Yalta, and Woland and his retinue have the flat.", text_zh: "杂耍剧院经理斯乔帕·利霍杰耶夫宿醉醒来，发现 50 号公寓里他的床边坐着一个穿黑衣的陌生人，手里拿着一份他不记得自己签过的合同。转眼之间，他已经站在雅尔塔的防波堤上，公寓归了沃兰德一伙。", highlight_en: ["flat no. 50"], highlight_zh: ["50 号公寓"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Master_and_Margarita" },
  { id: "mm-s3", kind: "scene", book_id: "master-and-margarita", place_ids: ["ru-pashkov-house"], location: "Chapter 29", location_zh: "第二十九章", text_en: "At sunset Woland and Azazello sit on the stone terrace of a building the novel calls one of the most beautiful in Moscow, looking out over the city. Matthew Levi comes to them there with the request that the Master be given peace.", text_zh: "日落时分，沃兰德和阿扎泽洛坐在一幢楼的石砌平台上俯瞰全城，小说说这是莫斯科最美的建筑之一。利未·马太来到这里，转达请求：赐予大师安宁。", highlight_en: ["the stone terrace"], highlight_zh: ["石砌平台"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Master_and_Margarita" },
  // —— 11-23: fifth pack, Siberia and the Far East (tools/content/batches/add_ru5.py) ——
  { id: "res-tomsk-1", book_id: "resurrection-tolstoy", place_ids: ["ru-tomsk"], location: "Part 3, chapter 1", location_zh: "第三部第一章", text_orig: "Партия, с которой шла Маслова, прошла около пяти тысяч верст.\n…\nПомещаться на этапах Масловой разрешено было с политическими, но идти она в качестве здоровой женщины должна была с уголовными. Так она шла все время от самого Томска.", highlight_orig: ["Томска"], text_en: "The party with which Maslova was travelling had covered about five thousand versts.\n…\nAt the halting stations Maslova was allowed to be lodged with the politicals, but as a healthy woman she had to walk with the criminals. So she had walked all the way from Tomsk.", highlight_en: ["Tomsk"], text_zh: "玛丝洛娃所在的那一队犯人已经走了将近五千俄里。\n…\n在各个驿站上，玛丝洛娃获准同政治犯住在一起，可是她身体健康，走路时必须同刑事犯在一起。从托木斯克起，她就一直这样走着。", highlight_zh: ["托木斯克"], translation: "own", status: "draft", checked: "Russian Wikisource, Воскресение (Толстой)/Часть III/Глава I (a gap marked …), 2026-11-23" },
  { id: "sib-1", book_id: "from-siberia", place_ids: ["ru-yenisei-krasnoyarsk"], location: "Sketch IX", location_zh: "第九篇", text_orig: "Не в обиду будь сказано ревнивым почитателям Волги, в своей жизни я не видел реки великолепнее Енисея. Пускай Волга нарядная, скромная, грустная красавица, зато Енисей могучий, неистовый богатырь, который не знает, куда девать свои силы и молодость.", highlight_orig: ["Енисея", "Енисей"], text_en: "Let it be said without offence to the jealous admirers of the Volga: in all my life I have never seen a river more magnificent than the Yenisei. The Volga may be a dressed-up, modest, melancholy beauty, but the Yenisei is a mighty, raging giant who does not know what to do with his strength and youth.", highlight_en: ["Yenisei"], text_zh: "请伏尔加河那些爱吃醋的崇拜者不要见怪：我这辈子没有见过比叶尼塞河更壮丽的河。就算伏尔加河是一位盛装的、朴素的、忧郁的美人，叶尼塞河却是一个强壮而狂暴的勇士，不知道该把自己的力气和青春往哪里使。", highlight_zh: ["叶尼塞河"], translation: "own", status: "draft", checked: "Russian Wikisource, Из Сибири (Чехов), 2026-11-23" },
  { id: "rud-1", book_id: "in-the-depths-of-siberian-mines", place_ids: ["ru-chita-decembrists"], location: "Stanza 1", location_zh: "第一节", text_orig: "Во глубине сибирских руд\nХраните гордое терпенье,\nНе пропадет ваш скорбный труд\nИ дум высокое стремленье.", highlight_orig: ["сибирских руд"], text_en: "Deep in the mines of Siberia\nkeep your proud patience;\nyour grievous toil will not be lost,\nnor the high striving of your thoughts.", highlight_en: ["mines of Siberia"], text_zh: "在西伯利亚矿坑的深处，\n请保持你们高傲的忍耐，\n你们沉痛的劳役不会落空，\n思想的崇高追求也不会徒然。", highlight_zh: ["西伯利亚矿坑"], translation: "own", status: "draft", checked: "Russian Wikisource, Во глубине сибирских руд (Пушкин), 2026-11-23" },
  { id: "mak-1", book_id: "makars-dream", place_ids: ["ru-amga"], location: "Chapter 1", location_zh: "第一章", text_orig: "Его родина — глухая слободка Чалган — затерялась в далёкой якутской тайге. Отцы и деды Макара отвоевали у тайги кусок промёрзшей землицы, и хотя угрюмая чаща всё ещё стояла кругом враждебною стеной, они не унывали.", highlight_orig: ["слободка Чалган"], text_en: "His home, the remote little settlement of Chalgan, lay lost in the far Yakut taiga. Makar's fathers and grandfathers had won from the taiga a patch of frozen earth, and although the sullen forest still stood all round like a hostile wall, they did not lose heart.", highlight_en: ["settlement of Chalgan"], text_zh: "他的家乡——偏僻的小村恰尔甘——湮没在遥远的雅库特原始森林里。马卡尔的父辈和祖辈从森林手里夺下了一小块冻土，尽管阴沉的密林仍像一堵敌意的墙围在四周，他们并不灰心。", highlight_zh: ["小村恰尔甘"], translation: "own", status: "draft", checked: "Russian Wikisource, Сон Макара (Короленко)/ПСС 1914 (ВТ:Ё), 2026-11-23" },
  { id: "avv-bk1", book_id: "life-of-avvakum", place_ids: ["ru-baikal"], location: "The return from Dauria", location_zh: "从达斡尔返回途中", text_orig: "Поехали из Даур, стало пищи скудать и с братиею бога помолили, и Христос нам дал изубря, большова зверя, — тем и до Байкалова моря доплыли. У моря русских людей наехала станица соболиная, рыбу промышляет; рады, миленькие, нам, и с карбасом нас, с моря ухватя, далеко на гору несли Терентьюшко с товарыщи; плачють, миленькие, глядя на нас, а мы на них.", highlight_orig: ["Байкалова моря"], text_en: "We set out from Dauria, and food began to run short, and with the brethren we prayed to God, and Christ gave us a great stag, a huge beast, and on that we floated as far as the Baikal sea. By the sea we came upon a band of Russians, sable hunters, catching fish; glad they were to see us, the dear souls, and Terentyushko and his comrades seized us, boat and all, out of the sea and carried us far up the hill; they wept, the dear souls, looking at us, and we at them.", highlight_en: ["Baikal sea"], text_zh: "我们从达斡尔动身，粮食渐渐不够了，我同弟兄们向上帝祈祷，基督赐给我们一头马鹿，好大的一头野兽——靠着它，我们一路漂到了贝加尔海。在海边遇上一伙俄罗斯人，是捕貂的，正在打鱼；这些好人见了我们真高兴，捷连季和他的伙伴们把我们连人带船从海里抬起来，远远地抬到山坡上；这些好人看着我们直哭，我们看着他们也哭。", highlight_zh: ["贝加尔海"], translation: "own", status: "draft", checked: "Russian Wikisource, Житие протопопа Аввакума, им самим написанное (Аввакум) (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "der-kf1", book_id: "dersu-uzala", place_ids: ["ru-korfovsky"], location: "Chapter 30, 'The Death of Dersu'", location_zh: "第三十章《德尔苏之死》", text_orig: "В 1910 году, зимой, я вернулся в Хабаровск и тотчас поехал на станцию Корфовскую, чтобы навестить дорогую могилу. Я не узнал места — все изменилось: около станции возник целый поселок, в пригорьях Хехцира открыли ломки гранита, начались порубки леса, заготовка шпал. Мы с И. А. Дзюль несколько раз принимались искать могилу Дерсу, но напрасно…", highlight_orig: ["станцию Корфовскую"], text_en: "In the winter of 1910 I returned to Khabarovsk and went at once to Korfovskaya station to visit the grave that was dear to me. I did not recognise the place; everything had changed: a whole settlement had sprung up round the station, granite quarries had been opened in the foothills of the Khekhtsir, timber was being felled and sleepers cut. I. A. Dzyul and I set about looking for Dersu's grave several times, but in vain…", highlight_en: ["Korfovskaya station"], text_zh: "1910 年冬天，我回到哈巴罗夫斯克，立刻赶往科尔福夫斯卡亚车站，去看那座我珍爱的坟墓。我认不出那个地方了——一切都变了：车站四周冒出了整整一个村镇，赫赫齐尔山脚下开了花岗岩采石场，人们在伐木、备枕木。我和伊·阿·久尔几次动手寻找德尔苏的墓，却都是徒劳……", highlight_zh: ["科尔福夫斯卡亚车站"], translation: "own", status: "draft", checked: "Russian Wikisource, Дерсу Узала/Полный текст/XXX. СМЕРТЬ ДЕРСУ (no-break and thin spaces written as plain spaces), 2026-11-23" },
  { id: "cp-ep1", book_id: "crime-and-punishment", place_ids: ["ru-omsk-fortress"], location: "Epilogue, chapter 1", location_zh: "尾声第一章", text_orig: "Сибирь. На берегу широкой, пустынной реки стоит город, один из административных центров России; в городе крепость, в крепости острог.", highlight_orig: ["Сибирь"], text_en: "Siberia. On the bank of a broad, deserted river stands a town, one of the administrative centres of Russia; in the town there is a fortress, in the fortress a prison.", highlight_en: ["Siberia"], text_zh: "西伯利亚。在一条宽阔而荒凉的大河岸上，有一座城，是俄国的行政中心之一；城里有一座要塞，要塞里有一座监狱。", highlight_zh: ["西伯利亚"], translation: "own", status: "draft", checked: "Russian Wikisource, Преступление и наказание (Достоевский)/Эпилог/I (hard-wrapped lines joined, doubled spaces written as one), 2026-11-23" },
  { id: "ms-bk1", book_id: "michael-strogoff", place_ids: ["ru-baikal"], location: "Part 2, chapter 10", location_zh: "第二部第十章", text_orig: "Cet immense bassin d’eau douce, alimenté par plus de trois cents rivières, est encadré dans un magnifique circuit de montagnes volcaniques. Il n’a d’autre déversoir que l’Angara, qui, après avoir passé à Irkoutsk, va se jeter dans l’Yeniseï, un peu en amont de la ville d’Yeniseïsk.", highlight_orig: ["l’Angara", "Irkoutsk"], text_en: "This immense basin of fresh water, fed by more than three hundred rivers, is framed in a magnificent circle of volcanic mountains. It has no other outlet than the Angara, which, after passing Irkutsk, goes on to join the Yenisei a little above the town of Yeniseisk.", highlight_en: ["Angara", "Irkutsk"], text_zh: "这片巨大的淡水湖由三百多条河流注入，四周环绕着一圈壮丽的火山山脉。它唯一的出口是安加拉河，河水流过伊尔库茨克之后，在叶尼塞斯克城上游不远处汇入叶尼塞河。", highlight_zh: ["安加拉河", "伊尔库茨克"], translation: "own", status: "draft", checked: "French Wikisource, Michel Strogoff/Partie 2/Chapitre 10, 2026-11-23" },
  { id: "zima-s1", kind: "scene", book_id: "zima-junction", place_ids: ["ru-zima"], location: "The whole poem", location_zh: "全诗", text_en: "At twenty the poet takes the train home from Moscow to the Siberian station town for the first time in years. He goes berry-picking with his cousins, listens to his uncles argue about what has gone wrong in the country, meets a woman on a hayloft and a drunk who was once somebody, and leaves with the station's own voice telling him to go on searching and not to lose heart.", text_zh: "二十岁的诗人多年来第一次从莫斯科坐火车回到西伯利亚的车站小城。他同表兄弟姐妹去采浆果，听舅舅们争论国家到底出了什么毛病，在干草棚上遇见一个女人，又遇见一个从前有头有脸的醉汉；临走时，车站用它自己的声音嘱咐他继续寻找，不要灰心。", highlight_en: ["the Siberian station town"], highlight_zh: ["西伯利亚的车站小城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Yevgeny_Yevtushenko" },
  { id: "rytk-s1", kind: "scene", book_id: "dream-in-polar-fog", place_ids: ["ru-anadyr"], location: "The whole novel", location_zh: "全书", text_en: "A Canadian sailor, John MacLennan, is badly injured aboard a ship off the Chukchi coast, and Chukchi hunters take him by sledge to their village, where his life is saved. The ship sails without him, and he stays, marries and learns to live as one of the village.", text_zh: "加拿大水手约翰·麦克伦南在楚科奇海岸外的一艘船上受了重伤，楚科奇猎人用雪橇把他送到自己的村子，救了他的命。船没有等他就开走了，他留了下来，成了家，学会像村里人一样生活。", highlight_en: ["the Chukchi coast"], highlight_zh: ["楚科奇海岸"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Yuri_Rytkheu" },
  { id: "zul-s2", kind: "scene", book_id: "zuleikha", place_ids: ["ru-angara"], location: "Parts 2–4", location_zh: "第二至第四部", text_en: "After months in a cattle wagon and a barge that sinks under them, some thirty survivors are put ashore on the empty bank of the Angara at the start of winter with one commandant, the Red Army man who shot Zuleikha's husband. She gives birth to a son, learns to hunt, and over sixteen years the dugout becomes the settlement of Semruk.", text_zh: "在闷罐车里熬了几个月、乘坐的驳船又沉没之后，三十来个幸存者在入冬时被丢在安加拉河荒无人烟的岸上，身边只有一个管制员——就是开枪打死祖列伊哈丈夫的那个红军战士。她生下一个儿子，学会了打猎；十六年里，那个地窝子变成了谢姆鲁克村。", highlight_en: ["the Angara"], highlight_zh: ["安加拉河"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Zuleikha_(novel)" },
  { id: "mat-s2", kind: "scene", book_id: "farewell-to-matyora", place_ids: ["ru-atalanka"], location: "The whole novel", location_zh: "全书", text_en: "In its last summer the island village is cleared for the reservoir: the graveyard crosses are pulled up by strangers, the young burn their own houses for the compensation, and old Darya whitewashes her hut one last time before it is set alight. She and a few other old people are still on the island when the fog comes down and the boat sent for them loses its way.", text_zh: "在最后一个夏天，岛上的村子要为水库让路：墓地的十字架被外人拔掉，年轻人为了领补偿烧掉自家的房子，老达丽娅在木屋被点燃之前最后一次把它粉刷了一遍。大雾降下来的时候，她和另外几个老人还留在岛上，来接他们的船在雾里迷了路。", highlight_en: ["the island village"], highlight_zh: ["岛上的村子"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Farewell_to_Matyora" },
  // —— 11-24: famous books hung on their nearest real place (tools/content/batches/add_ru6.py) ——
  { id: "ru-us-1", kind: "scene", book_id: "unknown-soldier", place_ids: ["ru-petrozavodsk"], location: "The advance of 1941", location_zh: "1941 年的进攻", text_en: "A Finnish machine-gun company goes to war in the summer of 1941, at the start of the Continuation War: the laconic Karelian Rokka, the quiet officer Koskela, good-natured Hietanen, the shirker Rahikainen and the rest of a crew of ordinary men from all over Finland, who mock their officers, grumble, and fight. In the attack phase their road leads east across Karelia to Petrozavodsk, which the Finns rename Äänislinna; then come the long years of trench war and the retreat of 1944. Linna, who had served as a machine-gunner himself, showed the war from the ranks, with fear and rebellion as well as courage.", text_zh: "1941 年夏天，继续战争开始，一个芬兰机枪连开赴前线：寡言的卡累利阿人罗卡、沉静的军官科斯凯拉、好脾气的希耶塔宁、偷懒耍滑的拉希凯宁，还有一群来自芬兰各地的普通人——他们挖苦军官、发牢骚，也打仗。进攻阶段，他们一路向东穿过卡累利阿，打到彼得罗扎沃茨克，芬兰人把它改名“Äänislinna”；接下来是漫长的堑壕战和 1944 年的撤退。林纳自己当过机枪手，他从士兵的角度写这场战争，写他们的恐惧和反抗，也写勇气。", highlight_en: ["Petrozavodsk", "Äänislinna"], highlight_zh: ["彼得罗扎沃茨克", "Äänislinna"], status: "draft", fact_source: "https://www.utupub.fi/handle/11111/41788 (Riku Kauhanen, Äänislinna-noir – Miehitetty Petroskoi suomalaisessa kirjallisuudessa); https://caponeu.ffzg.unizg.hr/cdp/novels/tuntematon-sotilas; https://en.wikipedia.org/wiki/The_Unknown_Soldier_(novel)" }
];
